window.QBANK = window.QBANK || {};
window.QBANK["smp-ppkn"] = {
  level: "SMP", subject: "PPKn", duration: 900,
  questions: [
    { q: "Bunyi sila kedua Pancasila adalah ....", options: ["Kemanusiaan yang adil dan beradab", "Persatuan Indonesia", "Ketuhanan Yang Maha Esa", "Keadilan sosial bagi seluruh rakyat Indonesia"], answer: 0, solution: "1. Urutan sila Pancasila: sila ke-1 Ketuhanan Yang Maha Esa, sila ke-2 Kemanusiaan yang adil dan beradab, sila ke-3 Persatuan Indonesia, sila ke-4 Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan, sila ke-5 Keadilan sosial bagi seluruh rakyat Indonesia. 2. Jadi bunyi sila kedua adalah Kemanusiaan yang adil dan beradab. 3. Pilihan lain adalah bunyi sila ke-3, ke-1, dan ke-5 sehingga salah." },
    { q: "Sinta menolong korban banjir dengan memberikan makanan dan pakaian tanpa membedakan suku dan agama mereka. Perbuatan Sinta merupakan pengamalan Pancasila sila ....", options: ["pertama", "kedua", "ketiga", "keempat"], answer: 1, solution: "1. Menolong sesama manusia tanpa membeda-bedakan suku dan agama adalah wujud nilai kemanusiaan. 2. Nilai kemanusiaan terkandung dalam sila kedua Pancasila, yaitu Kemanusiaan yang adil dan beradab. 3. Sila pertama tentang ketuhanan, sila ketiga tentang persatuan, dan sila keempat tentang kerakyatan, sehingga ketiganya kurang tepat." },
    { q: "Bunyi sila ketiga Pancasila adalah ....", options: ["Kemanusiaan yang adil dan beradab", "Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan", "Persatuan Indonesia", "Keadilan sosial bagi seluruh rakyat Indonesia"], answer: 2, solution: "1. Sila ketiga Pancasila berbunyi Persatuan Indonesia. 2. Sila ini mengandung nilai persatuan dan kesatuan bangsa Indonesia. 3. Pilihan lain adalah bunyi sila kedua, keempat, dan kelima sehingga salah." },
    { q: "Setiap hari Senin sekolah mengadakan upacara bendera. Kegiatan tersebut bertujuan menumbuhkan rasa ....", options: ["persatuan dan kesatuan bangsa", "individualisme dan persaingan", "acuh terhadap lingkungan", "kebebasan tanpa batas"], answer: 0, solution: "1. Upacara bendera melatih disiplin, menghormati jasa pahlawan, dan memperkuat rasa kebersamaan seluruh warga sekolah. 2. Rasa kebersamaan dan persatuan merupakan nilai sila ketiga Pancasila, yaitu Persatuan Indonesia. 3. Individualisme, sikap acuh, dan kebebasan tanpa batas justru bertentangan dengan nilai persatuan." },
    { q: "Bunyi sila keempat Pancasila adalah ....", options: ["Persatuan Indonesia", "Keadilan sosial bagi seluruh rakyat Indonesia", "Ketuhanan Yang Maha Esa", "Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan"], answer: 3, solution: "1. Sila keempat Pancasila berbunyi Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan. 2. Sila ini mengandung nilai demokrasi, musyawarah, dan perwakilan. 3. Pilihan lain adalah bunyi sila ketiga, kelima, dan pertama sehingga salah." },
    { q: "Dalam musyawarah pemilihan ketua kelas, Dina berbeda pendapat dengan temannya, tetapi ia tetap mendengarkan dan menghargai pendapat tersebut. Sikap Dina mencerminkan pengamalan sila ....", options: ["pertama", "keempat", "kedua", "ketiga"], answer: 1, solution: "1. Menghargai pendapat orang lain dalam musyawarah adalah wujud nilai kerakyatan. 2. Nilai kerakyatan dan musyawarah terkandung dalam sila keempat Pancasila. 3. Sila pertama tentang ketuhanan, sila kedua tentang kemanusiaan, dan sila ketiga tentang persatuan, sehingga ketiganya kurang tepat." },
    { q: "Bunyi sila kelima Pancasila adalah ....", options: ["Ketuhanan Yang Maha Esa", "Kemanusiaan yang adil dan beradab", "Keadilan sosial bagi seluruh rakyat Indonesia", "Persatuan Indonesia"], answer: 2, solution: "1. Sila kelima Pancasila berbunyi Keadilan sosial bagi seluruh rakyat Indonesia. 2. Sila ini mengandung nilai keadilan dan kesejahteraan bersama seluruh rakyat. 3. Pilihan lain adalah bunyi sila pertama, kedua, dan ketiga sehingga salah." },
    { q: "Pak Guru membagi tugas piket kelas secara merata dan adil kepada semua siswa tanpa pilih kasih. Tindakan Pak Guru mencerminkan sila ....", options: ["kelima", "kedua", "ketiga", "keempat"], answer: 0, solution: "1. Memberi perlakuan yang adil kepada semua orang adalah wujud nilai keadilan. 2. Nilai keadilan sosial terkandung dalam sila kelima Pancasila, yaitu Keadilan sosial bagi seluruh rakyat Indonesia. 3. Sila kedua tentang kemanusiaan, sila ketiga tentang persatuan, dan sila keempat tentang kerakyatan, sehingga ketiganya kurang tepat." },
    { q: "Pancasila disebut sebagai ideologi terbuka. Hal ini berarti ....", options: ["seluruh nilai Pancasila boleh diubah-ubah sesuai keinginan", "nilai dasar Pancasila tetap, tetapi terbuka terhadap perkembangan zaman", "Pancasila hanya berlaku untuk generasi tertentu", "Pancasila menolak semua pengaruh dari luar"], answer: 1, solution: "1. Ideologi terbuka artinya nilai-nilai dasarnya tidak berubah, tetapi penjabarannya dapat menyesuaikan perkembangan zaman. 2. Nilai dasar (lima sila) bersifat tetap, sedangkan nilai instrumentalnya seperti peraturan perundang-undangan dapat disesuaikan. 3. Anggapan bahwa semua nilai boleh diubah, hanya berlaku sementara, atau menolak pengaruh luar adalah miskonsepsi." },
    { q: "Menurut Prof. Notonagoro, nilai-nilai Pancasila terdiri atas tiga tingkatan, yaitu ....", options: ["nilai moral, nilai etika, dan nilai estetika", "nilai dasar, nilai hukum, dan nilai budaya", "nilai individu, nilai kelompok, dan nilai masyarakat", "nilai dasar, nilai instrumental, dan nilai praksis"], answer: 3, solution: "1. Notonagoro membagi nilai Pancasila menjadi tiga tingkatan nilai. 2. Ketiganya adalah nilai dasar (lima sila yang tetap dan tidak berubah), nilai instrumental (penjabaran nilai dasar, misalnya dalam UUD dan peraturan), dan nilai praksis (pengamalan nyata dalam kehidupan sehari-hari). 3. Pilihan lain bukan pembagian nilai menurut Notonagoro." },
    { q: "Pancasila sebagai dasar negara secara resmi tercantum dalam ....", options: ["Batang Tubuh UUD 1945 Pasal 1", "Pembukaan UUD 1945 alinea pertama", "Pembukaan UUD 1945 alinea keempat", "Piagam Jakarta"], answer: 2, solution: "1. Dasar negara Indonesia adalah Pancasila. 2. Rumusan Pancasila sebagai dasar negara tercantum dalam Pembukaan UUD 1945 alinea keempat. 3. Alinea pertama berisi pernyataan kemerdekaan, Piagam Jakarta adalah naskah awal sebelum disahkan, dan Batang Tubuh berisi pasal-pasal, bukan rumusan dasar negara." },
    { q: "Pancasila disahkan sebagai dasar negara Indonesia pada tanggal ....", options: ["18 Agustus 1945", "17 Agustus 1945", "1 Juni 1945", "22 Juni 1945"], answer: 0, solution: "1. Sehari setelah proklamasi kemerdekaan, PPKI bersidang dan mengesahkan UUD 1945 beserta dasar negara. 2. Pengesahan tersebut terjadi pada tanggal 18 Agustus 1945. 3. Tanggal 17 Agustus 1945 adalah proklamasi kemerdekaan, 1 Juni 1945 adalah hari lahir Pancasila (pidato Soekarno), dan 22 Juni 1945 adalah tanggal Piagam Jakarta." },
    { q: "Semboyan negara Indonesia Bhinneka Tunggal Ika memiliki arti ....", options: ["bersatu kita teguh bercerai kita runtuh", "berbeda-beda tetapi tetap satu jua", "bersama kita bisa mencapai cita-cita", "tiga warna dalam satu bendera"], answer: 1, solution: "1. Bhinneka Tunggal Ika adalah semboyan negara yang tertulis pada pita lambang Garuda Pancasila. 2. Artinya adalah berbeda-beda tetapi tetap satu jua, yang mencerminkan keberagaman suku, agama, dan budaya dalam satu kesatuan bangsa. 3. Pilihan lain bukan arti harfiah semboyan tersebut." },
    { q: "Semboyan Bhinneka Tunggal Ika berasal dari kitab ....", options: ["Negarakertagama karya Mpu Prapanca", "Ramayana karya Walmiki", "Sutasoma karya Mpu Tantular", "Mahabharata karya Wiyasa"], answer: 2, solution: "1. Bhinneka Tunggal Ika adalah semboyan negara Indonesia. 2. Semboyan tersebut berasal dari kitab Sutasoma karya Mpu Tantular pada zaman Kerajaan Majapahit. 3. Kitab Negarakertagama karya Mpu Prapanca juga berasal dari zaman Majapahit sehingga sering tertukar, sedangkan Ramayana dan Mahabharata adalah kisah kepahlawanan." },
    { q: "UUD 1945 disahkan oleh PPKI pada tanggal ....", options: ["17 Agustus 1945", "27 Desember 1949", "18 Agustus 1946", "18 Agustus 1945"], answer: 3, solution: "1. Setelah Indonesia merdeka pada 17 Agustus 1945, PPKI segera bersidang untuk menetapkan konstitusi negara. 2. Dalam sidangnya tanggal 18 Agustus 1945, PPKI mengesahkan UUD 1945. 3. Tanggal 17 Agustus 1945 adalah hari proklamasi, sedangkan pilihan tahun 1946 dan 1949 tidak tepat." },
    { q: "Sejak disahkan hingga sekarang, UUD 1945 telah mengalami amandemen sebanyak ....", options: ["2 kali", "4 kali", "3 kali", "5 kali"], answer: 1, solution: "1. Amandemen adalah perubahan terhadap UUD yang dilakukan oleh MPR. 2. UUD 1945 telah diamandemen sebanyak 4 kali, yaitu amandemen pertama tahun 1999, kedua tahun 2000, ketiga tahun 2001, dan keempat tahun 2002. 3. Jadi jawaban 2 kali, 3 kali, dan 5 kali tidak tepat." },
    { q: "Pembukaan UUD 1945 terdiri atas ....", options: ["4 alinea", "3 alinea", "5 alinea", "2 alinea"], answer: 0, solution: "1. Pembukaan UUD 1945 adalah bagian pembuka sebelum Batang Tubuh yang berisi pasal-pasal. 2. Pembukaan UUD 1945 terdiri atas 4 alinea yang memuat cita-cita, tujuan, dan dasar negara. 3. Pilihan 3, 5, dan 2 alinea tidak tepat." },
    { q: "Kalimat bahwa sesungguhnya kemerdekaan itu ialah hak segala bangsa dan oleh sebab itu penjajahan di atas dunia harus dihapuskan terdapat dalam Pembukaan UUD 1945 alinea ....", options: ["kedua", "ketiga", "pertama", "keempat"], answer: 2, solution: "1. Kalimat tentang hak segala bangsa atas kemerdekaan dan penghapusan penjajahan adalah pernyataan kemerdekaan bangsa Indonesia. 2. Pernyataan tersebut terdapat pada alinea pertama Pembukaan UUD 1945. 3. Alinea kedua berisi cita-cita perjuangan kemerdekaan, alinea ketiga berisi pernyataan kemerdekaan atas berkat rahmat Tuhan, dan alinea keempat berisi tujuan negara." },
    { q: "Salah satu tujuan negara Indonesia yang tercantum dalam Pembukaan UUD 1945 alinea keempat adalah ....", options: ["membentuk negara serikat Indonesia", "memajukan kesejahteraan umum", "menghapus seluruh perbedaan suku bangsa", "menjadikan Indonesia negara adidaya"], answer: 1, solution: "1. Alinea keempat Pembukaan UUD 1945 memuat tujuan negara Indonesia. 2. Tujuan tersebut adalah melindungi segenap bangsa Indonesia dan seluruh tumpah darah Indonesia, memajukan kesejahteraan umum, mencerdaskan kehidupan bangsa, dan ikut melaksanakan ketertiban dunia. 3. Pilihan lain bukan tujuan negara menurut Pembukaan UUD 1945." },
    { q: "Pasal 1 ayat (2) UUD 1945 menegaskan bahwa kedaulatan berada di tangan rakyat. Hal ini berarti ....", options: ["presiden memegang seluruh kekuasaan negara", "MPR adalah lembaga tertinggi negara", "rakyat tidak boleh ikut mengatur negara", "kekuasaan tertinggi negara berasal dari rakyat"], answer: 3, solution: "1. Pasal 1 ayat (2) UUD 1945 hasil amandemen berbunyi kedaulatan berada di tangan rakyat dan dilaksanakan menurut Undang-Undang Dasar. 2. Artinya kekuasaan tertinggi negara berasal dari rakyat, misalnya diwujudkan melalui pemilihan umum. 3. Anggapan MPR sebagai lembaga tertinggi negara adalah keadaan sebelum amandemen; kini semua lembaga negara berkedudukan sederajat." },
    { q: "Ketentuan bahwa Indonesia ialah negara kesatuan yang berbentuk republik tercantum dalam UUD 1945 ....", options: ["Pasal 1 ayat (1)", "Pasal 1 ayat (2)", "Pasal 4 ayat (1)", "Pembukaan alinea pertama"], answer: 0, solution: "1. Bentuk negara dan bentuk pemerintahan Indonesia diatur dalam pasal awal UUD 1945. 2. Pasal 1 ayat (1) berbunyi Negara Indonesia ialah negara kesatuan yang berbentuk republik. 3. Pasal 1 ayat (2) tentang kedaulatan rakyat dan Pasal 4 ayat (1) tentang kekuasaan pemerintahan presiden, sehingga keduanya bukan jawaban yang tepat." },
    { q: "Menurut Pasal 1 ayat (3) UUD 1945, Negara Indonesia adalah negara ....", options: ["kekuasaan", "komunis", "hukum", "liberal"], answer: 2, solution: "1. Pasal 1 ayat (3) UUD 1945 hasil amandemen menegaskan prinsip penyelenggaraan negara. 2. Bunyinya adalah Negara Indonesia adalah negara hukum, artinya segala tindakan penyelenggara negara harus berdasar pada hukum. 3. Negara kekuasaan berarti penguasa bertindak sewenang-wenang tanpa hukum, yang bertentangan dengan pasal ini." },
    { q: "Norma yang bersumber dari Tuhan Yang Maha Esa dan pelanggarnya diyakini mendapat dosa adalah norma ....", options: ["kesusilaan", "kesopanan", "hukum", "agama"], answer: 3, solution: "1. Setiap norma memiliki sumber dan sanksi yang berbeda. 2. Norma agama bersumber dari Tuhan Yang Maha Esa melalui kitab suci, dan pelanggarnya diyakini mendapat dosa atau azab. 3. Norma kesusilaan bersumber dari hati nurani, norma kesopanan dari tata tertib masyarakat, dan norma hukum dari negara." },
    { q: "Budi berbohong kepada orang tuanya. Setelah itu ia merasa sangat malu dan menyesal. Rasa malu dan menyesal tersebut merupakan sanksi dari norma ....", options: ["agama", "kesusilaan", "kesopanan", "hukum"], answer: 1, solution: "1. Sanksi setiap norma berbeda-beda bentuknya. 2. Rasa malu dan menyesal yang muncul dari hati nurani merupakan sanksi norma kesusilaan. 3. Sanksi norma agama berupa dosa, norma kesopanan berupa celaan masyarakat, dan norma hukum berupa hukuman tegas dari negara." },
    { q: "Rina tidak mau antre saat membeli makanan di kantin sehingga ia diejek dan dijauhi teman-temannya. Ejekan dan dijauhi teman merupakan sanksi dari norma ....", options: ["kesopanan", "kesusilaan", "agama", "hukum"], answer: 0, solution: "1. Tidak antre adalah perbuatan yang melanggar tata tertib dan kepatutan dalam pergaulan masyarakat. 2. Sanksi berupa ejekan, celaan, atau dikucilkan masyarakat merupakan sanksi norma kesopanan. 3. Rasa malu dari hati nurani adalah sanksi kesusilaan, dosa adalah sanksi agama, dan hukuman penjara adalah sanksi hukum." },
    { q: "Ciri yang membedakan norma hukum dari norma-norma lainnya adalah ....", options: ["sanksinya berupa rasa malu dan menyesal", "sanksinya berupa celaan masyarakat", "sanksinya tegas dan bersifat memaksa", "bersumber dari hati nurani manusia"], answer: 2, solution: "1. Semua norma mengatur tingkah laku manusia, tetapi norma hukum memiliki kekhasan. 2. Norma hukum dibuat oleh negara, sanksinya tegas seperti denda, kurungan, atau penjara, dan bersifat memaksa bagi semua orang. 3. Rasa malu adalah sanksi kesusilaan, celaan masyarakat adalah sanksi kesopanan, dan hati nurani adalah sumber kesusilaan." },
    { q: "Tujuan utama dibuatnya hukum dalam kehidupan masyarakat adalah ....", options: ["memperbanyak aturan yang mengikat warga", "menciptakan ketertiban, keadilan, dan kepastian hukum", "menghukum setiap warga negara yang bersalah", "membatasi kebebasan berpendapat warga"], answer: 1, solution: "1. Hukum hadir untuk mengatur kehidupan bersama agar berjalan tertib dan adil. 2. Tujuan hukum adalah menciptakan ketertiban, keadilan, dan kepastian hukum bagi masyarakat. 3. Memperbanyak aturan, sekadar menghukum, atau membatasi kebebasan berpendapat bukanlah tujuan hukum." },
    { q: "Rudi mengambil sepeda motor milik temannya tanpa izin lalu menjualnya. Perbuatan Rudi melanggar norma ....", options: ["kesopanan saja", "kesusilaan saja", "hukum", "tidak melanggar norma apa pun"], answer: 2, solution: "1. Mengambil barang milik orang lain tanpa izin adalah pencurian. 2. Pencurian diatur dan diancam hukuman dalam hukum pidana, sehingga perbuatan Rudi melanggar norma hukum. 3. Perbuatan ini bukan sekadar soal sopan santun atau hati nurani, melainkan tindak pidana yang sanksinya tegas dari negara." },
    { q: "Asas pemilihan umum di Indonesia adalah ....", options: ["langsung, umum, bebas, rahasia, jujur, dan adil", "langsung, bebas, terbuka, cepat, dan murah", "umum, tertutup, bebas, rahasia, dan adil", "langsung, umum, wajib, terbuka, dan jujur"], answer: 0, solution: "1. Pasal 22E ayat (1) UUD 1945 mengatur tentang pemilihan umum. 2. Pemilu dilaksanakan secara langsung, umum, bebas, rahasia, jujur, dan adil setiap lima tahun sekali, disingkat luber jurdil. 3. Asas wajib, tertutup, dan terbuka tidak termasuk asas pemilu di Indonesia." },
    { q: "Pemilihan umum di Indonesia dilaksanakan setiap ....", options: ["4 tahun sekali", "6 tahun sekali", "5 tahun sekali", "7 tahun sekali"], answer: 2, solution: "1. Jadwal pemilihan umum diatur dalam UUD 1945. 2. Pasal 22E ayat (1) menegaskan bahwa pemilu dilaksanakan setiap lima tahun sekali. 3. Pilihan 4 tahun, 6 tahun, dan 7 tahun tidak sesuai dengan ketentuan UUD 1945." },
    { q: "Dewan Perwakilan Rakyat (DPR) memiliki tiga fungsi, yaitu ....", options: ["mengubah UUD, melantik presiden, dan mengadili", "menguji UU, kasasi, dan yudisial", "memilih presiden, memilih menteri, dan mengadili", "legislasi, anggaran, dan pengawasan"], answer: 3, solution: "1. Fungsi DPR diatur dalam Pasal 20A ayat (1) UUD 1945. 2. Tiga fungsi DPR adalah fungsi legislasi (membentuk UU bersama presiden), fungsi anggaran (menetapkan APBN), dan fungsi pengawasan (mengawasi jalannya pemerintahan). 3. Mengubah UUD adalah wewenang MPR, mengadili tingkat kasasi adalah wewenang MA, dan menguji UU adalah wewenang MK, sehingga ketiganya sering tertukar." },
    { q: "Lembaga negara yang berwenang mengubah dan menetapkan Undang-Undang Dasar adalah ....", options: ["DPR", "MPR", "Presiden", "Mahkamah Konstitusi"], answer: 1, solution: "1. Kewenangan mengubah UUD diatur dalam Pasal 3 ayat (1) UUD 1945. 2. MPR berwenang mengubah dan menetapkan Undang-Undang Dasar. 3. DPR bersama presiden membentuk undang-undang (bukan UUD), presiden memegang kekuasaan pemerintahan, dan MK menguji UU terhadap UUD, sehingga ketiganya bukan jawaban yang tepat." },
    { q: "Dewan Perwakilan Daerah (DPD) dapat mengajukan rancangan undang-undang yang berkaitan dengan ....", options: ["otonomi daerah dan kepentingan daerah", "anggaran pendapatan dan belanja negara", "pembubaran partai politik", "pengangkatan duta besar"], answer: 0, solution: "1. DPD adalah lembaga perwakilan daerah yang anggotanya dipilih dari setiap provinsi. 2. Menurut Pasal 22D ayat (1), DPD dapat mengajukan rancangan UU yang berkaitan dengan otonomi daerah, hubungan pusat dan daerah, serta perimbangan keuangan pusat dan daerah. 3. APBN adalah wewenang DPR, pembubaran partai politik adalah wewenang MK, dan pengangkatan duta adalah wewenang presiden." },
    { q: "Ketentuan bahwa presiden memegang kekuasaan pemerintahan menurut Undang-Undang Dasar tercantum dalam ....", options: ["Pasal 1 ayat (2)", "Pasal 3 ayat (1)", "Pasal 4 ayat (1)", "Pasal 20 ayat (1)"], answer: 2, solution: "1. Indonesia menganut sistem pemerintahan presidensial, di mana presiden adalah kepala pemerintahan. 2. Pasal 4 ayat (1) UUD 1945 berbunyi Presiden Republik Indonesia memegang kekuasaan pemerintahan menurut Undang-Undang Dasar. 3. Pasal 1 ayat (2) tentang kedaulatan rakyat, Pasal 3 tentang wewenang MPR, dan Pasal 20 tentang pembentukan UU." },
    { q: "Mahkamah Agung berwenang mengadili pada tingkat ....", options: ["pertama dan terakhir", "banding", "pertama", "kasasi"], answer: 3, solution: "1. Mahkamah Agung adalah pelaku kekuasaan kehakiman pada tingkat tertinggi. 2. Menurut Pasal 24A ayat (1), Mahkamah Agung berwenang mengadili pada tingkat kasasi, yaitu memeriksa dan memutus perkara pada tingkat terakhir. 3. Mengadili pada tingkat pertama dan terakhir yang putusannya bersifat final adalah wewenang Mahkamah Konstitusi, bukan Mahkamah Agung." },
    { q: "Menguji undang-undang terhadap Undang-Undang Dasar merupakan wewenang ....", options: ["Mahkamah Agung", "Mahkamah Konstitusi", "Komisi Yudisial", "Dewan Perwakilan Rakyat"], answer: 1, solution: "1. Pengujian UU terhadap UUD di tingkat konstitusi disebut judicial review. 2. Menurut Pasal 24C ayat (1), Mahkamah Konstitusi berwenang menguji undang-undang terhadap Undang-Undang Dasar. 3. Mahkamah Agung hanya menguji peraturan di bawah UU terhadap UU (bukan terhadap UUD), Komisi Yudisial mengawasi perilaku hakim, dan DPR membentuk UU." },
    { q: "Sejak amandemen UUD 1945, Presiden dan Wakil Presiden dipilih oleh ....", options: ["rakyat secara langsung", "MPR", "DPR", "DPD"], answer: 0, solution: "1. Pasal 6A ayat (1) UUD 1945 hasil amandemen mengatur pemilihan presiden. 2. Presiden dan Wakil Presiden dipilih dalam satu pasangan secara langsung oleh rakyat. 3. Pemilihan oleh MPR adalah sistem sebelum amandemen UUD 1945 sehingga sering menjadi pengecoh." },
    { q: "Masa jabatan Presiden adalah lima tahun dan sesudahnya dapat dipilih kembali ....", options: ["sebanyak dua kali masa jabatan", "tanpa batas masa jabatan", "hanya untuk satu kali masa jabatan", "sebanyak tiga kali masa jabatan"], answer: 2, solution: "1. Pembatasan masa jabatan presiden diatur dalam UUD 1945 hasil amandemen. 2. Pasal 7 berbunyi Presiden dan Wakil Presiden memegang jabatan selama lima tahun, dan sesudahnya dapat dipilih kembali dalam jabatan yang sama, hanya untuk satu kali masa jabatan. 3. Jadi presiden paling lama menjabat 10 tahun, bukan tanpa batas." },
    { q: "Majelis Permusyawaratan Rakyat (MPR) terdiri atas ....", options: ["anggota DPR dan para menteri", "anggota DPR dan anggota DPD", "anggota DPD dan para gubernur", "anggota DPR dan hakim agung"], answer: 1, solution: "1. Susunan keanggotaan MPR diatur dalam UUD 1945. 2. Pasal 2 ayat (1) berbunyi MPR terdiri atas anggota DPR dan anggota DPD yang dipilih melalui pemilihan umum. 3. Menteri, gubernur, dan hakim agung bukan anggota MPR." },
    { q: "Prinsip kedaulatan rakyat dalam demokrasi berarti ....", options: ["seluruh kekuasaan negara dipegang presiden", "rakyat wajib menaati semua perintah penguasa", "kekuasaan negara dibagi kepada para bangsawan", "kekuasaan tertinggi negara berasal dari rakyat"], answer: 3, solution: "1. Demokrasi berasal dari kata demos yang berarti rakyat dan kratos yang berarti kekuasaan. 2. Kedaulatan rakyat berarti kekuasaan tertinggi negara berasal dari rakyat dan dilaksanakan untuk kepentingan rakyat, misalnya melalui pemilihan umum. 3. Kekuasaan yang dipegang presiden semata atau kewajiban menaati penguasa tanpa batas bertentangan dengan demokrasi." },
    { q: "Hak asasi manusia dalam UUD 1945 diatur secara rinci dalam ....", options: ["Pasal 28A sampai 28J", "Pasal 1 sampai Pasal 3", "Pembukaan alinea pertama", "Pasal 37"], answer: 0, solution: "1. Amandemen kedua UUD 1945 menambahkan pengaturan khusus tentang hak asasi manusia. 2. Hak asasi manusia diatur dalam Pasal 28A sampai dengan Pasal 28J UUD 1945. 3. Pasal 1 sampai 3 mengatur bentuk negara dan MPR, bukan hak asasi manusia." },
    { q: "Setiap orang berhak untuk hidup serta berhak mempertahankan hidup dan kehidupannya. Ketentuan tersebut tercantum dalam ....", options: ["Pasal 28B", "Pasal 27 ayat (1)", "Pasal 28A", "Pasal 29 ayat (1)"], answer: 2, solution: "1. Hak untuk hidup adalah hak asasi manusia yang paling mendasar. 2. Pasal 28A UUD 1945 berbunyi Setiap orang berhak untuk hidup serta berhak mempertahankan hidup dan kehidupannya. 3. Pasal 28B mengatur hak berkeluarga, Pasal 27 ayat (1) tentang kedudukan dalam hukum, dan Pasal 29 tentang agama." },
    { q: "Negara menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agamanya masing-masing dan beribadat menurut agamanya. Jaminan tersebut tercantum dalam ....", options: ["Pasal 28A", "Pasal 30 ayat (1)", "Pasal 27 ayat (3)", "Pasal 29 ayat (2)"], answer: 3, solution: "1. Kebebasan beragama adalah salah satu hak asasi manusia. 2. Pasal 29 ayat (2) UUD 1945 berbunyi Negara menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agamanya masing-masing dan untuk beribadat menurut agamanya dan kepercayaannya itu. 3. Pasal 28A tentang hak hidup, Pasal 30 tentang pertahanan negara, dan Pasal 27 ayat (3) tentang bela negara." },
    { q: "Setiap warga negara berhak mendapat pendidikan. Ketentuan tersebut tercantum dalam UUD 1945 ....", options: ["Pasal 32", "Pasal 31 ayat (1)", "Pasal 33", "Pasal 34"], answer: 1, solution: "1. Pendidikan adalah hak dasar setiap warga negara. 2. Pasal 31 ayat (1) UUD 1945 berbunyi Setiap warga negara berhak mendapat pendidikan. 3. Pasal 32 tentang kebudayaan, Pasal 33 tentang perekonomian, dan Pasal 34 tentang fakir miskin dan anak terlantar." },
    { q: "Tiap-tiap warga negara berhak atas pekerjaan dan penghidupan yang layak bagi kemanusiaan. Ketentuan tersebut merupakan bunyi ....", options: ["Pasal 27 ayat (2)", "Pasal 27 ayat (1)", "Pasal 28A", "Pasal 30 ayat (1)"], answer: 0, solution: "1. Hak atas pekerjaan adalah hak warga negara di bidang ekonomi dan kesejahteraan. 2. Pasal 27 ayat (2) UUD 1945 berbunyi Tiap-tiap warga negara berhak atas pekerjaan dan penghidupan yang layak bagi kemanusiaan. 3. Pasal 27 ayat (1) tentang kedudukan dalam hukum, Pasal 28A tentang hak hidup, dan Pasal 30 ayat (1) tentang pertahanan negara." },
    { q: "Setiap warga negara berhak dan wajib ikut serta dalam upaya pembelaan negara. Ketentuan tersebut tercantum dalam ....", options: ["Pasal 27 ayat (1)", "Pasal 28E ayat (1)", "Pasal 27 ayat (3)", "Pasal 30 ayat (2)"], answer: 2, solution: "1. Bela negara adalah hak sekaligus kewajiban setiap warga negara Indonesia. 2. Pasal 27 ayat (3) UUD 1945 berbunyi Setiap warga negara berhak dan wajib ikut serta dalam upaya pembelaan negara. 3. Pasal 30 ayat (1) mengatur keikutsertaan dalam usaha pertahanan dan keamanan negara yang sering tertukar, sedangkan Pasal 27 ayat (1) tentang kedudukan dalam hukum." },
    { q: "Contoh wujud bela negara yang dapat dilakukan oleh seorang pelajar adalah ....", options: ["ikut tawuran antar sekolah", "membolos sekolah untuk bermain", "menyebarkan kabar bohong di media sosial", "belajar dengan sungguh-sungguh dan menaati tata tertib sekolah"], answer: 3, solution: "1. Bela negara tidak selalu berarti angkat senjata; setiap warga dapat melakukannya sesuai dengan profesinya. 2. Bagi pelajar, bela negara diwujudkan dengan belajar sungguh-sungguh, disiplin, dan menaati tata tertib sekolah sebagai bekal membangun bangsa. 3. Tawuran, membolos, dan menyebarkan kabar bohong justru merugikan bangsa dan negara." },
    { q: "Sikap cinta tanah air dapat diwujudkan dalam kehidupan sehari-hari dengan cara ....", options: ["lebih bangga memakai produk luar negeri", "bangga memakai produk dalam negeri dan melestarikan budaya bangsa", "meniru semua gaya hidup bangsa asing", "acuh terhadap lingkungan sekitar"], answer: 1, solution: "1. Cinta tanah air berarti bangga menjadi bagian dari bangsa Indonesia. 2. Wujudnya antara lain bangga memakai produk dalam negeri, melestarikan budaya bangsa, dan menjaga lingkungan sekitar. 3. Lebih bangga pada produk asing, meniru gaya hidup asing, dan bersikap acuh justru menunjukkan kurangnya cinta tanah air." },
    { q: "Alat negara yang bertugas memelihara keamanan dan ketertiban masyarakat adalah ....", options: ["Tentara Nasional Indonesia", "Kepolisian Negara Republik Indonesia", "Komisi Pemberantasan Korupsi", "Badan Intelijen Negara"], answer: 1, solution: "1. Pasal 30 UUD 1945 membagi tugas pertahanan dan keamanan negara. 2. TNI bertugas mempertahankan dan melindungi keutuhan serta kedaulatan negara, sedangkan Polri bertugas memelihara keamanan dan ketertiban masyarakat serta menegakkan hukum. 3. KPK bertugas memberantas korupsi dan BIN di bidang intelijen, bukan keamanan dan ketertiban masyarakat." },
    { q: "Penyelesaian masalah melalui musyawarah untuk mencapai mufakat merupakan cerminan demokrasi ....", options: ["liberal", "terpimpin", "langsung", "Pancasila"], answer: 3, solution: "1. Demokrasi yang berlaku di Indonesia berlandaskan Pancasila. 2. Demokrasi Pancasila mengutamakan musyawarah untuk mencapai mufakat sesuai nilai sila keempat, yaitu Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan. 3. Demokrasi liberal mengutamakan kebebasan individu dan pemungutan suara, bukan musyawarah mufakat." },
    { q: "Bunyi sila pertama Pancasila adalah ....", options: ["Ketuhanan Yang Maha Esa","Kemanusiaan yang Adil dan Beradab","Persatuan Indonesia","Keadilan Sosial bagi Seluruh Rakyat Indonesia"], answer: 0, solution: "1. Sila pertama Pancasila berbunyi Ketuhanan Yang Maha Esa. 2. Ingat urutannya: 1 Ketuhanan, 2 Kemanusiaan, 3 Persatuan, 4 Kerakyatan, 5 Keadilan Sosial. 3. Jangan tertukar dengan sila kelima yang berbunyi Keadilan Sosial bagi Seluruh Rakyat Indonesia." },
    { q: "Sila kedua Pancasila dilambangkan dengan ....", options: ["pohon beringin","kepala banteng","rantai","bintang"], answer: 2, solution: "1. Lambang sila kedua Pancasila adalah rantai. 2. Pasangannya: bintang = sila 1, rantai = sila 2, beringin = sila 3, banteng = sila 4, padi-kapas = sila 5. 3. Banyak yang tertukar antara rantai (sila 2) dan pohon beringin (sila 3)." },
    { q: "Setiap manusia memiliki harkat dan martabat yang sama sehingga tidak boleh direndahkan atau diperlakukan sewenang-wenang. Pemahaman tersebut merupakan makna sila ....", options: ["pertama","kedua","kelima","ketiga"], answer: 1, solution: "1. Mengakui persamaan harkat dan martabat setiap manusia adalah makna sila kedua. 2. Sila kedua berbunyi Kemanusiaan yang Adil dan Beradab. 3. Jangan tertukar dengan sila kelima; sila 5 soal keadilan sosial, sedangkan sila 2 soal kemanusiaan." },
    { q: "Menempatkan kepentingan bangsa dan negara di atas kepentingan pribadi serta rela berkorban demi keutuhan Indonesia merupakan makna sila ....", options: ["pertama","kelima","kedua","ketiga"], answer: 3, solution: "1. Mendahulukan kepentingan bangsa dan rela berkorban adalah makna sila ketiga. 2. Sila ketiga berbunyi Persatuan Indonesia. 3. Jangan tertukar dengan sila keempat; musyawarah itu sila 4, persatuan itu sila 3." },
    { q: "Keputusan bersama harus diambil melalui musyawarah untuk mencapai mufakat dan setiap warga negara memiliki kedudukan yang sama dalam berpendapat. Hal ini merupakan makna sila ....", options: ["kelima","keempat","ketiga","pertama"], answer: 1, solution: "1. Musyawarah untuk mencapai mufakat adalah inti sila keempat. 2. Sila keempat berbunyi Kerakyatan yang Dipimpin oleh Hikmat Kebijaksanaan dalam Permusyawaratan/Perwakilan. 3. Sila 4 sering tertukar dengan sila 3; ingat kata kunci musyawarah = sila 4." },
    { q: "Sikap tidak boros, menghargai hasil karya orang lain, serta berbuat adil kepada sesama merupakan cerminan pengamalan sila ....", options: ["ketiga","pertama","kelima","kedua"], answer: 2, solution: "1. Tidak boros dan berbuat adil adalah cerminan sila kelima. 2. Sila kelima berbunyi Keadilan Sosial bagi Seluruh Rakyat Indonesia. 3. Jangan tertukar dengan sila kedua; sila 2 soal kemanusiaan, sila 5 soal keadilan dan kesejahteraan." },
    { q: "Andi beragama Islam, sedangkan tetangganya beragama Kristen. Andi tidak pernah mengganggu saat tetangganya beribadah dan mereka saling membantu. Sikap Andi mencerminkan pengamalan sila ....", options: ["pertama","kedua","ketiga","keempat"], answer: 0, solution: "1. Tidak mengganggu ibadah pemeluk agama lain adalah sikap toleransi beragama. 2. Toleransi dan kebebasan beribadah adalah pengamalan sila pertama. 3. Menolong tanpa membedakan suku memang baik, tetapi karena fokusnya soal ibadah, jawabannya sila 1 bukan sila 2." },
    { q: "Rian menjenguk temannya yang sedang sakit dan membantu mengerjakan tugas kelompoknya yang tertinggal. Perbuatan Rian merupakan pengamalan sila ....", options: ["pertama","kelima","ketiga","kedua"], answer: 3, solution: "1. Menjenguk dan membantu teman yang sakit adalah sikap kemanusiaan. 2. Menjunjung tinggi nilai kemanusiaan adalah pengamalan sila kedua. 3. Ini bukan sila 3 karena perbuatannya tidak berkaitan dengan persatuan bangsa." },
    { q: "Warga desa bergotong royong membersihkan saluran air dan memperbaiki jalan yang rusak. Kegiatan tersebut mencerminkan pengamalan sila ....", options: ["kedua","ketiga","kelima","keempat"], answer: 1, solution: "1. Gotong royong menunjukkan kekompakan dan kebersamaan warga. 2. Menjaga persatuan dan kesatuan adalah pengamalan sila ketiga. 3. Jangan tertukar dengan sila 5; kerja bakti soal persatuan, bukan keadilan." },
    { q: "Saat rapat OSIS, ketua memimpin diskusi dan setiap anggota diberi kesempatan menyampaikan pendapat sebelum keputusan diambil bersama. Cara tersebut mencerminkan pengamalan sila ....", options: ["ketiga","kelima","keempat","pertama"], answer: 2, solution: "1. Setiap anggota berpendapat lalu diputuskan bersama adalah musyawarah. 2. Menghargai pendapat dan bermusyawarah adalah pengamalan sila keempat. 3. Ini bukan sekadar kerja sama (sila 3) karena ada proses musyawarah untuk mencapai mufakat." },
    { q: "Bu guru memberikan nilai berdasarkan usaha dan kemampuan masing-masing siswa, bukan berdasarkan kedekatan pribadi. Sikap Bu guru mencerminkan sila ....", options: ["kelima","kedua","ketiga","keempat"], answer: 0, solution: "1. Memberi nilai secara adil tanpa pilih kasih adalah sikap adil. 2. Berbuat adil kepada sesama adalah pengamalan sila kelima. 3. Jangan tertukar dengan sila kedua; adil di sini soal keadilan sosial, bukan soal kemanusiaan." },
    { q: "Salah satu contoh nyata Pancasila sebagai ideologi terbuka adalah ....", options: ["nilai dasar Pancasila tidak boleh berubah, tetapi penjabarannya disesuaikan dengan perkembangan zaman", "Pancasila diganti setiap ada pergantian presiden", "seluruh nilai Pancasila boleh diubah sesuai keinginan penguasa", "Pancasila hanya berlaku untuk satu generasi saja"], answer: 0, solution: "1. Ideologi terbuka artinya nilai dasarnya tetap tetapi terbuka terhadap perkembangan zaman. 2. Contohnya UUD 1945 diamandemen dan undang-undang diperbarui, sedangkan nilai Pancasilanya tidak berubah. 3. Salah kaprah: ideologi terbuka bukan berarti Pancasila boleh diganti seenaknya oleh penguasa." },
    { q: "Salah satu ciri ideologi tertutup yang TIDAK dimiliki Pancasila sebagai ideologi terbuka adalah ....", options: ["mampu menyesuaikan diri dengan zaman","bersumber dari nilai budaya bangsa","menjunjung musyawarah dan demokrasi","bersifat dogmatis dan tidak boleh dipertanyakan"], answer: 3, solution: "1. Ideologi tertutup bersifat dogmatis, mutlak, dan tidak boleh dipertanyakan. 2. Contohnya ideologi komunisme yang kaku dan tertutup. 3. Pancasila justru kebalikannya: terbuka, dinamis, dan bersumber dari budaya bangsa." },
    { q: "Menurut Prof. Notonagoro, nilai yang bersifat paling abstrak dan menjadi cita-cita serta tujuan yang hendak dicapai bangsa Indonesia disebut nilai ....", options: ["dasar","instrumental","praksis","hukum"], answer: 0, solution: "1. Nilai dasar adalah nilai yang paling abstrak berupa cita-cita bangsa. 2. Contohnya sila-sila Pancasila dalam Pembukaan UUD 1945. 3. Jangan tertukar dengan nilai instrumental yang berupa peraturan perundang-undangan." },
    { q: "Undang-Undang Dasar 1945 dan peraturan perundang-undangan yang menjabarkan nilai-nilai Pancasila termasuk dalam nilai ....", options: ["dasar","instrumental","praksis","moral"], answer: 1, solution: "1. Nilai instrumental adalah penjabaran nilai dasar dalam bentuk aturan. 2. UUD 1945 dan undang-undang adalah contoh nilai instrumental. 3. Bedanya dengan nilai praksis: instrumental masih berupa aturan tertulis, praksis berupa perbuatan nyata." },
    { q: "Contoh nyata nilai praksis Pancasila dalam kehidupan sehari-hari adalah ....", options: ["rumusan sila-sila dalam Pembukaan UUD 1945","pasal-pasal dalam undang-undang","pidato kenegaraan presiden","siswa menaati tata tertib sekolah dan menghormati guru"], answer: 3, solution: "1. Nilai praksis adalah pelaksanaan nilai Pancasila dalam perbuatan nyata sehari-hari. 2. Menaati tata tertib dan menghormati guru adalah contohnya. 3. Rumusan sila dan pasal undang-undang bukan praksis, melainkan nilai dasar dan instrumental." },
    { q: "Sidang pertama BPUPKI yang membahas dasar negara Indonesia merdeka dilaksanakan pada tanggal ....", options: ["18 Agustus 1945","29 Mei – 1 Juni 1945","22 Juni 1945","7 Agustus 1945"], answer: 1, solution: "1. BPUPKI mengadakan sidang pertama pada 29 Mei sampai 1 Juni 1945. 2. Sidang ini membahas dasar negara Indonesia merdeka. 3. Jangan tertukar dengan 18 Agustus 1945; itu sidang PPKI yang mengesahkan UUD." },
    { q: "Istilah Pancasila pertama kali dikemukakan oleh Ir. Soekarno dalam pidatonya pada sidang BPUPKI tanggal ....", options: ["29 Mei 1945","22 Juni 1945","1 Juni 1945","18 Agustus 1945"], answer: 2, solution: "1. Soekarno pertama kali menyebut istilah Pancasila dalam pidato 1 Juni 1945. 2. Tanggal 1 Juni kemudian diperingati sebagai Hari Lahir Pancasila. 3. Yamin berpidato 29 Mei dan Soepomo 31 Mei, tetapi istilah Pancasila berasal dari Soekarno." },
    { q: "Panitia Sembilan merumuskan Piagam Jakarta pada tanggal 22 Juni 1945. Bunyi sila pertama dalam Piagam Jakarta adalah ....", options: ["Ketuhanan Yang Maha Esa","Ketuhanan dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya","Kebangsaan Indonesia","Ketuhanan yang berkebudayaan"], answer: 1, solution: "1. Piagam Jakarta dirumuskan Panitia Sembilan pada 22 Juni 1945. 2. Sila pertamanya berbunyi Ketuhanan dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya. 3. Bunyi inilah yang kemudian diubah menjadi Ketuhanan Yang Maha Esa." },
    { q: "Pada sidang PPKI 18 Agustus 1945, tujuh kata pada sila pertama Piagam Jakarta diubah menjadi Yang Maha Esa. Perubahan tersebut dilakukan karena ....", options: ["adanya keberatan dari wakil-wakil Indonesia bagian timur agar semua pemeluk agama dapat menerimanya","agar bunyinya lebih singkat","usulan dari pemerintah Jepang","agar sama dengan bunyi sila yang lain"], answer: 0, solution: "1. Tujuh kata tentang syariat Islam diganti karena ada keberatan dari Indonesia bagian timur. 2. Tujuannya agar sila pertama dapat diterima semua pemeluk agama. 3. Perubahan ini menunjukkan semangat persatuan, bukan paksaan." },
    { q: "Badan yang mengesahkan Pancasila sebagai dasar negara pada tanggal 18 Agustus 1945 adalah ....", options: ["BPUPKI","Panitia Sembilan","PPKI","KNIP"], answer: 2, solution: "1. PPKI (Panitia Persiapan Kemerdekaan Indonesia) bersidang pada 18 Agustus 1945. 2. Sidang inilah yang mengesahkan UUD 1945 beserta Pancasila sebagai dasar negara. 3. Jangan tertukar dengan BPUPKI yang bertugas menyelidiki dan mempersiapkan, bukan mengesahkan." },
    { q: "Pemberontakan PKI di Madiun pada tahun 1948 bertujuan mengganti Pancasila dengan ideologi ....", options: ["liberalisme","kapitalisme","fasisme","komunisme"], answer: 3, solution: "1. Pemberontakan PKI di Madiun tahun 1948 dipimpin oleh Muso. 2. Tujuannya mengganti Pancasila dengan ideologi komunisme. 3. Pemberontakan ini akhirnya ditumpas oleh TNI." },
    { q: "Gerakan 30 September 1965 (G30S/PKI) menculik dan membunuh para perwira TNI Angkatan Darat. Peristiwa tersebut merupakan ancaman terhadap Pancasila karena ....", options: ["menuntut kemerdekaan daerah","bertujuan mengganti ideologi Pancasila dengan komunisme","menolak hasil pemilu","menuntut perubahan sistem pemerintahan daerah"], answer: 1, solution: "1. G30S/PKI pada 30 September 1965 menculik dan membunuh perwira TNI AD. 2. Tujuannya mengganti Pancasila dengan ideologi komunisme. 3. Gerakan ini gagal sehingga Pancasila tetap tegak sebagai dasar negara." },
    { q: "Bangsa Indonesia memperingati Hari Kesaktian Pancasila setiap tanggal 1 Oktober untuk mengenang ....", options: ["lahirnya Pancasila","disahkannya UUD 1945","kegagalan pemberontakan G30S/PKI yang hendak mengganti Pancasila","proklamasi kemerdekaan"], answer: 2, solution: "1. Setiap 1 Oktober diperingati Hari Kesaktian Pancasila. 2. Peringatan ini mengenang kegagalan G30S/PKI yang hendak mengganti Pancasila. 3. Jangan tertukar dengan 1 Juni yang merupakan Hari Lahir Pancasila." },
    { q: "Pemberontakan DI/TII yang dipimpin Kartosuwirjo bertujuan ....", options: ["mendirikan negara Islam dan mengganti Pancasila sebagai dasar negara","memisahkan diri dari NKRI karena alasan ekonomi","mengganti presiden dengan cara kudeta militer","menuntut otonomi daerah yang lebih luas"], answer: 0, solution: "1. DI/TII dipimpin Kartosuwirjo dan memproklamasikan Negara Islam Indonesia tahun 1949. 2. Tujuannya mengganti Pancasila dengan dasar negara Islam. 3. Berbeda dengan PRRI yang soal pemerintahan daerah, DI/TII jelas bersifat anti-Pancasila." },
    { q: "Pemberontakan PRRI di Sumatera dan Permesta di Sulawesi pada tahun 1958 merupakan ancaman terhadap ....", options: ["kebebasan beragama","keutuhan Negara Kesatuan Republik Indonesia","sistem pendidikan nasional","perekonomian rakyat"], answer: 1, solution: "1. PRRI (1958, Sumatera) dan Permesta (Sulawesi) adalah pemberontakan daerah. 2. Keduanya mengancam keutuhan NKRI. 3. Meski tidak seideologis DI/TII atau PKI, keduanya tetap pemberontakan terhadap negara." },
    { q: "Kitab Negarakertagama yang juga memuat istilah Pancasila dikarang oleh ....", options: ["Mpu Tantular","Mpu Prapanca","Empu Gandring","Ranggawarsita"], answer: 1, solution: "1. Kitab Negarakertagama dikarang Mpu Prapanca pada zaman Majapahit (1365). 2. Dalam kakawin ini istilah 'Pancasila' disebut sebagai lima dasar perilaku. 3. Jangan tertukar dengan Mpu Tantular yang mengarang kitab Sutasoma tempat semboyan Bhinneka Tunggal Ika berasal." },
    { q: "Meskipun berbeda suku, agama, dan budaya, seluruh rakyat Indonesia tetap bersatu dalam satu bangsa. Pernyataan tersebut merupakan wujud pengamalan semboyan ....", options: ["Tut Wuri Handayani","Bhinneka Tunggal Ika","Bhineka Tunggal Dharma","Tri Hita Karana"], answer: 1, solution: "1. Berbeda suku dan agama tetapi tetap satu bangsa adalah semangat Bhinneka Tunggal Ika. 2. Semboyan ini berarti berbeda-beda tetapi tetap satu jua. 3. Tut Wuri Handayani adalah semboyan pendidikan, bukan semboyan negara." },
    { q: "Jumlah bulu pada Garuda Pancasila melambangkan tanggal Proklamasi Kemerdekaan Indonesia, yaitu ....", options: ["20 helai pada sayap, 8 helai pada ekor, 45 helai di leher","17 helai pada sayap, 5 helai pada ekor, 45 helai di leher","17 helai pada sayap, 8 helai pada ekor, 19 helai di pangkal ekor, 45 helai di leher","17 helai pada sayap, 8 helai pada ekor, 45 helai di leher"], answer: 2, solution: "1. Bulu Garuda Pancasila melambangkan 17-8-1945. 2. Rinciannya: 17 helai tiap sayap, 8 helai ekor, 19 helai pangkal ekor, 45 helai leher. 3. Opsi yang hanya menyebut 17-8-45 tanpa 19 helai pangkal ekor itu tidak lengkap." },
    { q: "Pohon beringin yang menjadi lambang sila ketiga Pancasila melambangkan ....", options: ["tempat berteduh dan persatuan seluruh rakyat Indonesia","kekuatan militer Indonesia","kesuburan tanah air","keberanian bangsa Indonesia"], answer: 0, solution: "1. Pohon beringin adalah lambang sila ketiga. 2. Beringin yang besar dan rindang melambangkan tempat berteduh dan persatuan seluruh rakyat Indonesia. 3. Jangan tertukar dengan padi dan kapas yang melambangkan kemakmuran (sila 5)." },
    { q: "Padi dan kapas sebagai lambang sila kelima melambangkan ....", options: ["kekuatan dan keberanian","persatuan dan kesatuan","kemakmuran dan kesejahteraan rakyat","kedaulatan rakyat"], answer: 2, solution: "1. Padi dan kapas adalah lambang sila kelima. 2. Keduanya melambangkan kemakmuran dan kesejahteraan rakyat (sandang dan pangan). 3. Jangan tertukar dengan pohon beringin yang melambangkan persatuan (sila 3)." },
    { q: "Pancasila disebut sebagai pandangan hidup bangsa Indonesia. Hal ini berarti ....", options: ["Pancasila hanya dipelajari di sekolah","Pancasila hanya berlaku bagi pejabat negara","Pancasila diganti setiap ada pergantian presiden","Pancasila menjadi pedoman dalam bersikap dan berperilaku sehari-hari"], answer: 3, solution: "1. Pandangan hidup artinya pedoman dalam bersikap dan berperilaku. 2. Pancasila menjadi pedoman hidup sehari-hari bangsa Indonesia. 3. Bukan sekadar pelajaran sekolah, tetapi harus diamalkan dalam kehidupan nyata." },
    { q: "Pancasila sebagai kepribadian bangsa Indonesia berarti ....", options: ["semua warga negara harus memiliki wajah yang sama","nilai-nilai Pancasila menjadi ciri khas yang membedakan bangsa Indonesia dengan bangsa lain","bahasa Indonesia wajib dipakai di seluruh dunia","adat istiadat daerah harus dihapuskan"], answer: 1, solution: "1. Kepribadian bangsa artinya ciri khas suatu bangsa. 2. Nilai-nilai Pancasila menjadi ciri yang membedakan Indonesia dari bangsa lain. 3. Bukan soal wajah atau bahasa, melainkan nilai dan karakter bangsa." },
    { q: "Pancasila sebagai sumber dari segala sumber hukum berarti ....", options: ["semua peraturan perundang-undangan di Indonesia tidak boleh bertentangan dengan nilai-nilai Pancasila","hanya Pancasila yang boleh menjadi peraturan","hukum adat tidak berlaku lagi di Indonesia","semua hukum harus ditulis dalam bahasa Sansekerta"], answer: 0, solution: "1. Pancasila adalah sumber dari segala sumber hukum di Indonesia. 2. Artinya semua peraturan tidak boleh bertentangan dengan nilai-nilai Pancasila. 3. Bukan berarti hanya Pancasila yang jadi peraturan; undang-undang tetap dibuat tetapi harus selaras dengannya." },
    { q: "Rumusan Pancasila sebagai dasar negara secara resmi tercantum dalam Pembukaan UUD 1945 alinea ....", options: ["pertama","kedua","ketiga","keempat"], answer: 3, solution: "1. Dasar negara Indonesia tercantum dalam Pembukaan UUD 1945. 2. Tepatnya pada alinea keempat yang memuat rumusan Pancasila. 3. Alinea pertama sampai ketiga berisi latar belakang dan tujuan kemerdekaan." },
    { q: "Dito selalu merawat barang-barang miliknya, tidak membeli barang yang tidak dibutuhkan, dan menghargai karya teman-temannya. Sikap Dito mencerminkan sila ....", options: ["kedua","ketiga","kelima","keempat"], answer: 2, solution: "1. Tidak boros dan menghargai karya orang lain adalah sikap hemat dan adil. 2. Sikap tersebut mencerminkan sila kelima. 3. Ini bukan sila 2 karena fokusnya pada keadilan dan kesederhanaan hidup, bukan kemanusiaan." },
    { q: "Tokoh yang mengusulkan nama Pancasila untuk dasar negara Indonesia adalah ....", options: ["Moh. Hatta","Ir. Soekarno","Mr. Soepomo","Mr. Muhammad Yamin"], answer: 1, solution: "1. Istilah Pancasila dikemukakan Ir. Soekarno pada 1 Juni 1945. 2. Kata Pancasila berasal dari bahasa Sansekerta: panca artinya lima dan sila artinya dasar. 3. Yamin dan Soepomo juga berpidato soal dasar negara, tetapi nama Pancasila berasal dari Soekarno." },
    { q: "Perbedaan Piagam Jakarta dengan Pembukaan UUD 1945 adalah ....", options: ["Piagam Jakarta memuat sila pertama dengan tujuh kata tentang syariat Islam, sedangkan Pembukaan UUD 1945 memuat Ketuhanan Yang Maha Esa","keduanya sama persis tanpa perbedaan","Piagam Jakarta disahkan setelah Pembukaan UUD 1945","Piagam Jakarta ditulis dalam bahasa Belanda"], answer: 0, solution: "1. Piagam Jakarta memuat sila pertama dengan tujuh kata tentang syariat Islam. 2. Pembukaan UUD 1945 memuat Ketuhanan Yang Maha Esa setelah diubah oleh PPKI. 3. Salah kaprah umum: keduanya dianggap sama, padahal ada perbedaan penting ini." },
    { q: "Fajar selalu melaksanakan ibadah sesuai ajaran agamanya dan menjauhi larangannya. Aturan yang ditaati Fajar tersebut termasuk norma ....", options: ["kesusilaan", "kesopanan", "hukum", "agama"], answer: 3, solution: "1. Norma agama bersumber dari wahyu Tuhan yang tercantum dalam kitab suci. 2. Ibadah dan larangan agama adalah aturan yang bersumber dari ajaran agama. 3. Jangan tertukar dengan norma kesusilaan yang bersumber dari hati nurani, bukan dari Tuhan." },
    { q: "Doni mencontek saat ulangan. Setelah itu ia merasa bersalah dan hatinya tidak tenang. Rasa bersalah tersebut merupakan sanksi dari norma ....", options: ["kesusilaan", "agama", "hukum", "kesopanan"], answer: 0, solution: "1. Norma kesusilaan bersumber dari hati nurani manusia. 2. Sanksinya berupa rasa malu, menyesal, dan bersalah di dalam hati. 3. Jangan tertukar dengan norma kesopanan yang sanksinya berupa celaan atau ejekan dari orang lain." },
    { q: "Tono membuang sampah sembarangan di jalan, lalu ia ditegur dan dicela oleh warga sekitar. Teguran tersebut merupakan sanksi dari norma ....", options: ["hukum", "agama", "kesopanan", "kesusilaan"], answer: 2, solution: "1. Norma kesopanan bersumber dari pergaulan dan kebiasaan masyarakat. 2. Sanksinya berupa teguran, celaan, ejekan, atau dikucilkan. 3. Jangan tertukar dengan norma hukum yang sanksinya berupa denda atau hukuman dari aparat." },
    { q: "Norma hukum bersifat memaksa. Artinya ....", options: ["hanya berlaku bagi pejabat", "setiap orang wajib menaatinya dan pelanggar dikenai sanksi tegas", "boleh ditaati boleh tidak", "hanya berupa anjuran moral"], answer: 1, solution: "1. Sifat memaksa berarti hukum mengikat semua orang tanpa kecuali. 2. Pelanggarnya dikenai sanksi tegas oleh aparat negara. 3. Jangan dikira hukum hanya anjuran; hukum berbeda dengan norma kesopanan yang tidak memaksa." },
    { q: "Salah satu fungsi hukum dalam kehidupan masyarakat adalah ....", options: ["menambah kekayaan negara", "membatasi kebebasan beragama", "menyelesaikan perselisihan secara adil", "menghapus semua adat istiadat"], answer: 2, solution: "1. Hukum berfungsi mengatur tingkah laku agar kehidupan tertib. 2. Hukum juga menjadi alat menyelesaikan sengketa secara adil. 3. Jangan tertukar: hukum justru melindungi kebebasan beragama, bukan membatasinya." },
    { q: "Dengan adanya hukum, hak setiap warga negara menjadi ....", options: ["terlindungi dan terjamin", "boleh diabaikan", "milik pemerintah saja", "tidak berlaku lagi"], answer: 0, solution: "1. Salah satu tujuan hukum adalah melindungi hak warga negara. 2. Hukum memberi kepastian sehingga hak tidak dirampas sewenang-wenang. 3. Jangan tertukar: hukum melindungi hak rakyat, bukan memonopolinya untuk pemerintah." },
    { q: "Perbuatan mencuri, menipu, dan menganiaya diancam dengan hukuman penjara. Perbuatan-perbuatan tersebut diatur dalam hukum ....", options: ["perdata", "adat", "pidana", "internasional"], answer: 2, solution: "1. Hukum pidana mengatur perbuatan yang dilarang dengan ancaman hukuman. 2. Mencuri, menipu, dan menganiaya adalah tindak pidana. 3. Jangan tertukar dengan hukum perdata yang mengatur hubungan antarorang, bukan kejahatan." },
    { q: "Sengketa pembagian harta warisan antara para ahli waris diselesaikan berdasarkan hukum ....", options: ["pidana", "perdata", "militer", "internasional"], answer: 1, solution: "1. Hukum perdata mengatur hubungan hak dan kewajiban antarindividu. 2. Warisan, utang-piutang, dan jual beli termasuk hukum perdata. 3. Jangan tertukar dengan hukum pidana yang mengatur kejahatan seperti pencurian." },
    { q: "Rina meminjam uang kepada Sari dan tidak mengembalikannya sesuai janji. Kasus ini termasuk ranah hukum ....", options: ["pidana karena merugikan orang", "pidana karena ingkar janji selalu dipenjara", "pelanggaran kesopanan", "perdata karena soal utang-piutang"], answer: 3, solution: "1. Utang-piutang adalah hubungan keperdataan antarindividu. 2. Penyelesaiannya lewat gugatan ganti rugi, bukan hukuman penjara. 3. Miskonsepsi umum: tidak semua perbuatan merugikan adalah pidana; ingkar janji utang itu perdata." },
    { q: "Undang-undang dan peraturan pemerintah termasuk contoh hukum ....", options: ["tidak tertulis", "tertulis", "adat", "kebiasaan"], answer: 1, solution: "1. Hukum tertulis adalah hukum yang dicantumkan dalam peraturan resmi. 2. Undang-undang dibuat dan disahkan oleh lembaga negara. 3. Jangan tertukar dengan hukum adat yang tidak tertulis dan diwariskan turun-temurun." },
    { q: "Aturan adat yang diwariskan turun-temurun dan ditaati oleh masyarakat termasuk hukum ....", options: ["tertulis", "pidana", "tidak tertulis", "internasional"], answer: 2, solution: "1. Hukum tidak tertulis tidak dicantumkan dalam undang-undang. 2. Hukum adat hidup dalam kebiasaan masyarakat. 3. Jangan tertukar dengan hukum tertulis seperti KUHP yang dibukukan." },
    { q: "Perjanjian antara Indonesia dan Malaysia mengenai batas wilayah diatur oleh hukum ....", options: ["nasional", "adat", "internasional", "pidana"], answer: 2, solution: "1. Hukum internasional mengatur hubungan antarnegara. 2. Perjanjian batas wilayah melibatkan dua negara berdaulat. 3. Jangan tertukar dengan hukum nasional yang hanya berlaku di dalam satu negara." },
    { q: "Berikut ini yang termasuk unsur perbuatan melawan hukum adalah ....", options: ["ada niat baik dari pelakunya", "ada perbuatan yang melanggar aturan dan menimbulkan kerugian", "korban memaafkan pelaku", "perbuatan dilakukan tidak sengaja tanpa kerugian"], answer: 1, solution: "1. Perbuatan melawan hukum harus bertentangan dengan aturan hukum. 2. Perbuatan itu menimbulkan kerugian bagi pihak lain. 3. Miskonsepsi: dimaafkan korban tidak menghapus sifat melawan hukumnya." },
    { q: "Tahap awal ketika polisi mencari tahu apakah benar telah terjadi tindak pidana disebut ....", options: ["penyidikan", "penuntutan", "penyelidikan", "persidangan"], answer: 2, solution: "1. Penyelidikan adalah tahap awal mencari ada tidaknya tindak pidana. 2. Setelah jelas ada pidana, barulah dilakukan penyidikan. 3. Jangan tertukar: penyelidikan = mencari tahu, penyidikan = mengumpulkan bukti dan menetapkan tersangka." },
    { q: "Polisi telah mengumpulkan cukup bukti lalu menetapkan seseorang sebagai tersangka. Tahap ini disebut ....", options: ["penyidikan", "penyelidikan", "penuntutan", "vonis"], answer: 0, solution: "1. Penyidikan dilakukan setelah ada bukti permulaan yang cukup. 2. Pada tahap ini penyidik mencari bukti dan menetapkan tersangka. 3. Jangan tertukar dengan penuntutan yang dilakukan jaksa setelah berkas lengkap." },
    { q: "Jaksa melimpahkan berkas perkara ke pengadilan agar disidangkan. Tugas jaksa tersebut disebut ....", options: ["penyidikan", "penuntutan", "penyelidikan", "pembelaan"], answer: 1, solution: "1. Penuntutan adalah kewenangan jaksa melimpahkan perkara ke pengadilan. 2. Jaksa bertindak sebagai penuntut umum di sidang. 3. Jangan tertukar: penyidikan oleh polisi, penuntutan oleh jaksa, pembelaan oleh pengacara." },
    { q: "Aparat penegak hukum yang bertugas menjaga keamanan, mengatur lalu lintas, dan menyidik tindak pidana adalah ....", options: ["jaksa", "hakim", "polisi", "pengacara"], answer: 2, solution: "1. Polisi bertugas memelihara keamanan dan ketertiban masyarakat. 2. Polisi juga menjadi penyidik tindak pidana. 3. Jangan tertukar dengan jaksa yang tugasnya menuntut di pengadilan." },
    { q: "Pejabat yang memeriksa perkara dan menjatuhkan putusan di pengadilan adalah ....", options: ["jaksa", "polisi", "hakim", "pengacara"], answer: 2, solution: "1. Hakim memimpin jalannya persidangan di pengadilan. 2. Hakim yang memutuskan bersalah atau tidaknya terdakwa. 3. Jangan tertukar: jaksa menuntut, pengacara membela, hakim memutus." },
    { q: "Seseorang yang memberi bantuan hukum dan membela terdakwa di pengadilan disebut ....", options: ["pengacara", "jaksa", "hakim", "panitera"], answer: 0, solution: "1. Pengacara (advokat) mendampingi dan membela kliennya. 2. Setiap terdakwa berhak mendapat bantuan hukum. 3. Jangan tertukar dengan jaksa yang justru menuntut terdakwa." },
    { q: "Pengendara yang tidak memakai helm ditilang dan dikenai denda oleh polisi. Denda tersebut merupakan sanksi dari norma ....", options: ["kesopanan", "kesusilaan", "agama", "hukum"], answer: 3, solution: "1. Aturan lalu lintas ditetapkan dalam undang-undang. 2. Pelanggarnya dikenai sanksi tegas berupa tilang atau denda. 3. Jangan tertukar dengan norma kesopanan yang sanksinya hanya teguran atau celaan." },
    { q: "Hak dasar yang dimiliki setiap manusia sejak lahir sebagai anugerah Tuhan Yang Maha Esa disebut ....", options: ["hak asasi manusia", "hak warga negara", "hak istimewa", "hak politik"], answer: 0, solution: "1. HAM adalah hak dasar yang melekat pada diri manusia sejak lahir. 2. HAM merupakan anugerah Tuhan, bukan pemberian negara. 3. Jangan tertukar dengan hak warga negara yang hanya dimiliki warga suatu negara." },
    { q: "HAM berlaku untuk semua orang tanpa membedakan suku, agama, dan bangsa. Hal ini menunjukkan HAM bersifat ....", options: ["terbatas", "universal", "sementara", "khusus"], answer: 1, solution: "1. Universal artinya berlaku untuk seluruh manusia di dunia. 2. Tidak ada perbedaan suku, agama, ras, atau bangsa. 3. Jangan tertukar dengan hak warga negara yang terbatas hanya untuk warga negara tertentu." },
    { q: "HAM tidak dapat dicabut oleh siapa pun, termasuk oleh negara. Sifat HAM tersebut disebut ....", options: ["tidak dapat dicabut", "dapat dibagi-bagi", "dapat ditukar", "bersifat sementara"], answer: 0, solution: "1. HAM melekat pada diri manusia dan tidak dapat dicabut. 2. Negara wajib menghormati dan melindunginya. 3. Miskonsepsi: hukuman penjara membatasi kebebasan bergerak, tetapi tidak mencabut kemanusiaan seseorang." },
    { q: "Setiap anak berhak atas kelangsungan hidup, tumbuh dan berkembang, serta perlindungan dari kekerasan dan diskriminasi. Ketentuan ini tercantum dalam UUD 1945 ....", options: ["Pasal 28B", "Pasal 28A", "Pasal 28C", "Pasal 28D"], answer: 0, solution: "1. Pasal 28B ayat (2) mengatur hak anak secara khusus. 2. Anak berhak atas kelangsungan hidup dan perlindungan dari kekerasan. 3. Jangan tertukar dengan Pasal 28A yang mengatur hak untuk hidup secara umum." },
    { q: "Setiap orang berhak mengembangkan diri melalui pendidikan serta memperoleh manfaat dari ilmu pengetahuan dan teknologi. Ketentuan ini tercantum dalam UUD 1945 ....", options: ["Pasal 28B", "Pasal 28D", "Pasal 28C", "Pasal 28E"], answer: 2, solution: "1. Pasal 28C ayat (1) mengatur hak mengembangkan diri. 2. Termasuk hak atas pendidikan, ilmu pengetahuan, teknologi, seni, dan budaya. 3. Jangan tertukar dengan Pasal 31 yang mengatur kewajiban pemerintah menyelenggarakan pendidikan." },
    { q: "Setiap orang berhak atas pengakuan, jaminan, perlindungan, dan kepastian hukum yang adil. Ketentuan ini tercantum dalam UUD 1945 ....", options: ["Pasal 28E", "Pasal 28F", "Pasal 28C", "Pasal 28D"], answer: 3, solution: "1. Pasal 28D ayat (1) menjamin kepastian hukum yang adil. 2. Setiap orang sama kedudukannya di hadapan hukum. 3. Jangan tertukar dengan Pasal 28E yang mengatur kebebasan berpendapat dan beragama." },
    { q: "Setiap orang berhak atas kebebasan meyakini kepercayaan serta menyatakan pikiran dan sikap sesuai hati nuraninya. Kebebasan ini dijamin dalam UUD 1945 ....", options: ["Pasal 28D", "Pasal 28G", "Pasal 28F", "Pasal 28E"], answer: 3, solution: "1. Pasal 28E mengatur kebebasan beragama, berpendapat, dan berserikat. 2. Menyatakan pikiran sesuai hati nurani termasuk kebebasan berpendapat. 3. Jangan tertukar dengan Pasal 28F yang mengatur hak berkomunikasi dan memperoleh informasi." },
    { q: "Setiap orang berhak atas rasa aman dan perlindungan dari ancaman ketakutan untuk berbuat atau tidak berbuat sesuatu. Ketentuan ini tercantum dalam UUD 1945 ....", options: ["Pasal 28F", "Pasal 28H", "Pasal 28G", "Pasal 28I"], answer: 2, solution: "1. Pasal 28G ayat (1) menjamin hak atas rasa aman. 2. Termasuk bebas dari penyiksaan dan perlakuan merendahkan martabat. 3. Jangan tertukar dengan Pasal 28H yang mengatur hak atas kesejahteraan." },
    { q: "Setiap orang berhak hidup sejahtera lahir dan batin, bertempat tinggal, dan mendapatkan lingkungan hidup yang baik dan sehat. Ketentuan ini tercantum dalam UUD 1945 ....", options: ["Pasal 28I", "Pasal 28G", "Pasal 28J", "Pasal 28H"], answer: 3, solution: "1. Pasal 28H ayat (1) mengatur hak atas kesejahteraan dan lingkungan sehat. 2. Termasuk hak atas tempat tinggal dan pelayanan kesehatan. 3. Jangan tertukar dengan Pasal 28G yang mengatur hak atas rasa aman." },
    { q: "Hak untuk tidak disiksa serta hak kemerdekaan pikiran dan hati nurani tidak dapat dikurangi dalam keadaan apa pun. Ketentuan ini tercantum dalam UUD 1945 ....", options: ["Pasal 28H", "Pasal 28J", "Pasal 28I", "Pasal 29"], answer: 2, solution: "1. Pasal 28I ayat (1) memuat hak-hak yang tidak dapat dikurangi. 2. Termasuk hak tidak disiksa, tidak diperbudak, dan diakui sebagai pribadi di muka hukum. 3. Miskonsepsi: tidak semua HAM mutlak; hanya hak-hak dalam Pasal 28I yang tidak dapat dikurangi." },
    { q: "Setiap orang wajib menghormati hak asasi manusia orang lain dalam kehidupan bermasyarakat, berbangsa, dan bernegara. Ketentuan ini tercantum dalam UUD 1945 ....", options: ["Pasal 28J", "Pasal 28H", "Pasal 28I", "Pasal 30"], answer: 0, solution: "1. Pasal 28J ayat (1) menegaskan kewajiban menghormati HAM orang lain. 2. Hak seseorang dibatasi oleh hak orang lain. 3. Jangan tertukar dengan Pasal 28I yang mengatur hak yang tidak dapat dikurangi." },
    { q: "Kewajiban setiap orang untuk menghormati hak orang lain dan menaati aturan disebut ....", options: ["kewajiban asasi", "hak asasi", "hak istimewa", "kewajiban negara"], answer: 0, solution: "1. Kewajiban asasi adalah kewajiban dasar yang melekat pada setiap orang. 2. Contohnya menghormati hak orang lain dan menaati peraturan. 3. Jangan tertukar dengan hak asasi yang merupakan sesuatu yang diterima, bukan dikerjakan." },
    { q: "Berikut ini yang merupakan contoh kewajiban asasi warga negara adalah ....", options: ["mendapat perlindungan hukum", "membayar pajak dan menaati peraturan", "memilih dalam pemilu", "mendapat pendidikan gratis"], answer: 1, solution: "1. Kewajiban asasi adalah sesuatu yang harus dilaksanakan. 2. Membayar pajak dan menaati peraturan adalah kewajiban. 3. Miskonsepsi: mendapat perlindungan dan pendidikan adalah hak, bukan kewajiban." },
    { q: "Contoh pelanggaran HAM ringan adalah ....", options: ["pembunuhan berencana", "penyiksaan hingga tewas", "pencemaran nama baik", "genosida"], answer: 2, solution: "1. Pelanggaran HAM ringan tidak menghilangkan nyawa korban. 2. Contohnya pencemaran nama baik, fitnah, dan penganiayaan ringan. 3. Jangan tertukar dengan pelanggaran berat seperti pembunuhan dan genosida." },
    { q: "Contoh pelanggaran HAM berat adalah ....", options: ["mengejek teman di kelas", "pembunuhan massal (genosida)", "memukul hingga luka ringan", "tidak antre di kantin"], answer: 1, solution: "1. Pelanggaran HAM berat menghilangkan hak hidup banyak orang. 2. Contohnya genosida, pembunuhan massal, dan penyiksaan berat. 3. Miskonsepsi: mengejek atau memukul ringan termasuk pelanggaran ringan, bukan berat." },
    { q: "Berikut ini yang termasuk contoh norma hukum di lingkungan sekolah adalah ....", options: ["tata tertib sekolah", "berdoa sebelum pelajaran dimulai", "bersikap sopan kepada guru", "merasa malu setelah mencontek"], answer: 0, solution: "1. Tata tertib sekolah adalah aturan tertulis yang dibuat lembaga dan pelanggarnya dikenai sanksi resmi. 2. Berdoa adalah norma agama, sopan santun adalah norma kesopanan, rasa malu adalah sanksi norma kesusilaan. 3. Ciri norma hukum: tertulis, resmi, dan sanksinya tegas — seperti tata tertib." },
    { q: "Setiap orang berhak untuk bekerja serta mendapat imbalan dan perlakuan yang adil dan layak dalam hubungan kerja. Ketentuan ini tercantum dalam UUD 1945 ....", options: ["Pasal 27 ayat (2)", "Pasal 28D ayat (2)", "Pasal 28E ayat (1)", "Pasal 31 ayat (1)"], answer: 1, solution: "1. Pasal 28D ayat (2) menjamin hak atas pekerjaan serta imbalan dan perlakuan yang adil dan layak. 2. Pasal 27 ayat (2) memang juga menyebut pekerjaan yang layak, tetapi rumusan 'imbalan dan perlakuan yang adil dan layak dalam hubungan kerja' adalah bunyi Pasal 28D ayat (2). 3. Jangan tertukar: 28D soal jaminan hukum dan hak bekerja, 27 soal kedudukan warga negara." },
    { q: "Budi meminjam buku pelajaran milik temannya tanpa izin dan tidak mengembalikannya. Dari sudut pandang hak asasi manusia, perbuatan Budi melanggar hak temannya atas ....", options: ["rasa aman", "kepemilikan (hak milik)", "pendidikan", "berpendapat"], answer: 1, solution: "1. Pasal 28H ayat (4) UUD 1945 menjamin setiap orang berhak mempunyai hak milik pribadi. 2. Mengambil barang milik orang lain tanpa izin melanggar hak miliknya. 3. Bukan soal pendidikan atau pendapat — bendanya diambil, jadi yang dilanggar adalah hak milik." },
    { q: "Kata 'demokrasi' berasal dari bahasa Yunani, yaitu 'demos' dan 'kratos'. Arti gabungan kedua kata tersebut adalah ....", options: ["kekuasaan berada di tangan rakyat","kekuasaan berada di tangan raja","kekuasaan berada di tangan kaum bangsawan","kekuasaan berada di tangan pemuka agama"], answer: 0, solution: "1. 'Demos' artinya rakyat, sedangkan 'kratos' artinya kekuasaan atau pemerintahan. 2. Jadi demokrasi berarti pemerintahan yang kekuasaannya berada di tangan rakyat. 3. Jangan terkecoh: kekuasaan di tangan raja disebut monarki, bukan demokrasi." },
    { q: "Salah satu prinsip utama demokrasi adalah persamaan. Dalam kehidupan bernegara, prinsip ini diwujudkan melalui ....", options: ["hanya orang kaya yang boleh menjadi pejabat","setiap warga negara memiliki hak pilih yang sama dalam pemilu","keputusan diambil oleh satu orang pemimpin","rakyat dilarang menyampaikan pendapat"], answer: 1, solution: "1. Persamaan berarti setiap warga negara diperlakukan sama di depan hukum dan dalam politik. 2. Contoh nyatanya: satu orang satu suara dalam pemilu, tanpa membedakan kaya atau miskin. 3. Miskonsepsi: persamaan bukan berarti semua orang harus menjadi pejabat, melainkan hak politik yang sama." },
    { q: "Demokrasi Pancasila merupakan demokrasi yang dijiwai nilai-nilai Pancasila, terutama sila ....", options: ["pertama","kedua","keempat","kelima"], answer: 2, solution: "1. Sila keempat berbunyi kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan/perwakilan. 2. Rumusan inilah yang menjadi dasar demokrasi ala Indonesia. 3. Jangan tertukar: sila kelima mengatur keadilan sosial, bukan demokrasi." },
    { q: "Ciri khas demokrasi Pancasila yang membedakannya dari demokrasi liberal adalah ....", options: ["kebebasan individu tanpa batas","keputusan selalu diambil lewat voting","kepentingan individu di atas kepentingan bersama","mengutamakan musyawarah untuk mufakat"], answer: 3, solution: "1. Demokrasi liberal menonjolkan kebebasan individu dan pengambilan keputusan lewat voting. 2. Demokrasi Pancasila mengedepankan musyawarah untuk mufakat dan semangat kekeluargaan. 3. Jangan terkecoh: voting hanya jalan terakhir bila mufakat tidak tercapai." },
    { q: "Asas pemilu 'LUBER' merupakan singkatan dari ....", options: ["luas, umum, bersama, rahasia","langsung, umum, bebas, rahasia","langsung, utama, bebas, resmi","lancar, umum, bebas, rahasia"], answer: 1, solution: "1. LUBER adalah singkatan dari Langsung, Umum, Bebas, Rahasia. 2. Artinya pemilih mencoblos sendiri tanpa perantara dan pilihannya dirahasiakan. 3. Jangan terkecoh opsi yang mirip: tidak ada kata 'luas' atau 'lancar' dalam asas pemilu." },
    { q: "Asas 'JURDIL' dalam pemilu merupakan singkatan dari ....", options: ["jujur dan disiplin","jelas dan adil","jujur dan adil","jujur dan damai"], answer: 2, solution: "1. JURDIL adalah singkatan dari Jujur dan Adil. 2. Penyelenggara pemilu harus jujur dalam menghitung suara dan adil kepada semua peserta. 3. Jadi asas lengkap pemilu di Indonesia adalah Luber Jurdil." },
    { q: "Dalam pemilu legislatif, peserta pemilu untuk memilih anggota DPR dan DPRD adalah ...., sedangkan anggota DPD dipilih secara ....", options: ["partai politik ... perseorangan","perseorangan ... partai politik","partai politik ... partai politik","organisasi masyarakat ... perseorangan"], answer: 0, solution: "1. Anggota DPR dan DPRD dipilih melalui partai politik peserta pemilu. 2. Anggota DPD dipilih secara perseorangan karena mewakili daerah atau provinsi, bukan partai. 3. Jangan tertukar: DPD bukan berasal dari partai politik." },
    { q: "Pada hari pemungutan suara, setiap pemilih menerima 5 surat suara untuk 5 kotak suara. Kelima surat suara tersebut digunakan untuk memilih ....", options: ["Presiden-Wapres, MPR, MA, MK, BPK","DPR, DPD, MPR, gubernur, bupati","Presiden, DPR, DPD, kepala desa, ketua RT","Presiden-Wapres, DPR, DPD, DPRD provinsi, DPRD kabupaten/kota"], answer: 3, solution: "1. Pemilu memilih Presiden dan Wakil Presiden, DPR, DPD, DPRD Provinsi, serta DPRD Kabupaten/Kota. 2. Itulah isi dari 5 kotak suara pada pemilu. 3. Miskonsepsi: MPR, MA, MK, dan BPK tidak dipilih lewat pemilu karena anggotanya diangkat melalui mekanisme lain." },
    { q: "Surat suara untuk memilih Presiden dan Wakil Presiden berwarna ....", options: ["kuning","abu-abu","merah","hijau"], answer: 1, solution: "1. Warna surat suara pemilu: abu-abu untuk Presiden-Wapres, kuning untuk DPR, merah untuk DPD. 2. Biru untuk DPRD provinsi dan hijau untuk DPRD kabupaten/kota. 3. Jangan tertukar: surat suara kuning itu untuk DPR, bukan presiden." },
    { q: "Lembaga yang bertugas menyelenggarakan pemilu, seperti mendaftar pemilih dan menghitung hasil suara, adalah ....", options: ["Bawaslu","DKPP","KPU","MK"], answer: 2, solution: "1. KPU (Komisi Pemilihan Umum) adalah lembaga penyelenggara pemilu. 2. Bawaslu bertugas mengawasi, sedangkan DKPP menegakkan kode etik penyelenggara. 3. Jangan tertukar: MK hanya memutus sengketa hasil pemilu, bukan menyelenggarakannya." },
    { q: "Jika ada dugaan kecurangan dalam pelaksanaan pemilu, lembaga yang berwenang mengawasinya adalah ....", options: ["Bawaslu","KPU","DPR","Kepolisian"], answer: 0, solution: "1. Bawaslu (Badan Pengawas Pemilu) bertugas mengawasi jalannya pemilu. 2. KPU menyelenggarakan pemilu, Bawaslu mengawasi — tugas keduanya berbeda. 3. Jangan tertukar: DKPP mengawasi perilaku penyelenggara pemilu, bukan kecurangan peserta." },
    { q: "DKPP (Dewan Kehormatan Penyelenggara Pemilu) bertugas ....", options: ["menghitung perolehan suara pemilu","menetapkan calon presiden terpilih","mengawasi jalannya kampanye","menegakkan kode etik anggota KPU dan Bawaslu"], answer: 3, solution: "1. DKPP menjaga kehormatan serta menegakkan kode etik penyelenggara pemilu, yaitu KPU dan Bawaslu. 2. DKPP tidak menghitung suara dan tidak mengawasi kampanye. 3. Jangan tertukar dengan Bawaslu yang mengawasi pelaksanaan pemilu." },
    { q: "Jumlah anggota DPR RI periode 2024-2029 adalah ....", options: ["575 orang","580 orang","550 orang","600 orang"], answer: 1, solution: "1. Pada pemilu 2024 ditetapkan 580 kursi anggota DPR RI. 2. Jumlah ini bertambah dari periode sebelumnya yang berjumlah 575 kursi. 3. Jangan tertukar dengan DPD yang berjumlah 152 orang." },
    { q: "Setiap provinsi diwakili oleh 4 orang anggota DPD. Jika Indonesia memiliki 38 provinsi, jumlah anggota DPD adalah ....", options: ["120 orang","136 orang","144 orang","152 orang"], answer: 3, solution: "1. Perhitungannya: 4 orang dikali 38 provinsi sama dengan 152 orang. 2. Anggota DPD dipilih secara perseorangan, bukan dari partai politik. 3. Jangan tertukar dengan DPR yang berjumlah 580 orang." },
    { q: "Setelah Presiden dan Wakil Presiden terpilih dalam pemilu, lembaga yang berwenang melantik mereka adalah ....", options: ["MPR","DPR","MA","KPU"], answer: 0, solution: "1. MPR berwenang melantik Presiden dan Wakil Presiden menurut UUD 1945. 2. MPR juga menetapkan Presiden dan Wakil Presiden bila keduanya berhalangan tetap. 3. Jangan tertukar: KPU hanya menetapkan hasil pemilu, bukan melantik." },
    { q: "Urutan proses pemberhentian Presiden dalam masa jabatannya menurut UUD 1945 adalah ....", options: ["MK mengusulkan, DPR memeriksa, MPR memutuskan","DPR mengusulkan, MK memeriksa dan memutus, MPR memutuskan","MPR mengusulkan, DPR memeriksa, MK memutuskan","Presiden mengundurkan diri, DPR menyetujui"], answer: 1, solution: "1. DPR menyampaikan pendapat atau usul pemberhentian kepada MPR. 2. MK memeriksa, mengadili, dan memutus pendapat DPR tersebut. 3. Jika terbukti bersalah, MPR yang memutuskan pemberhentian — jadi MPR selalu di akhir, bukan di awal." },
    { q: "Salah satu syarat menjadi calon Presiden menurut peraturan perundang-undangan adalah ....", options: ["warga negara Indonesia dan berusia sekurang-kurangnya 25 tahun","pernah menjadi anggota DPR sekurang-kurangnya 5 tahun","berasal dari partai politik terbesar","warga negara Indonesia sejak kelahirannya dan berusia sekurang-kurangnya 40 tahun"], answer: 3, solution: "1. Calon presiden harus WNI sejak kelahirannya dan tidak pernah menerima kewarganegaraan lain karena kehendaknya sendiri. 2. Batas usia minimal calon presiden adalah 40 tahun. 3. Miskonsepsi: tidak ada syarat harus pernah menjadi anggota DPR atau berasal dari partai terbesar." },
    { q: "DPR bersama Presiden membahas dan menyetujui rancangan undang-undang. Kegiatan tersebut merupakan pelaksanaan fungsi ....", options: ["anggaran","pengawasan","legislasi","yudikatif"], answer: 2, solution: "1. Fungsi legislasi adalah membentuk undang-undang bersama Presiden. 2. Fungsi anggaran berkaitan dengan APBN, sedangkan fungsi pengawasan mengawasi pelaksanaan undang-undang. 3. Jangan tertukar: yudikatif adalah kekuasaan kehakiman (MA dan MK), bukan DPR." },
    { q: "DPR memberikan persetujuan atas rancangan APBN yang diajukan Presiden. Kegiatan tersebut merupakan pelaksanaan fungsi ....", options: ["anggaran","legislasi","pengawasan","eksekutif"], answer: 0, solution: "1. Fungsi anggaran membahas dan menyetujui APBN bersama Presiden. 2. Fungsi legislasi membuat undang-undang, fungsi pengawasan mengawasi jalannya pemerintahan. 3. Jangan tertukar: eksekutif adalah kekuasaan presiden, bukan DPR." },
    { q: "DPR memanggil seorang menteri untuk dimintai keterangan tentang pelaksanaan program pemerintah. Kegiatan tersebut merupakan pelaksanaan fungsi ....", options: ["legislasi","pengawasan","anggaran","yudikatif"], answer: 1, solution: "1. Fungsi pengawasan adalah mengawasi pelaksanaan undang-undang dan kebijakan pemerintah. 2. Contohnya melalui rapat kerja, hak interpelasi, dan hak angket. 3. Jangan tertukar dengan legislasi yang hanya berkaitan dengan pembuatan undang-undang." },
    { q: "Untuk menyelidiki dugaan pelanggaran hukum dalam pelaksanaan kebijakan pemerintah, DPR dapat menggunakan hak ....", options: ["interpelasi","menyatakan pendapat","budget","angket"], answer: 3, solution: "1. Hak angket adalah hak DPR untuk melakukan penyelidikan terhadap pelaksanaan suatu undang-undang atau kebijakan. 2. Hak interpelasi hanya meminta keterangan kepada pemerintah. 3. Jangan tertukar: interpelasi sekadar bertanya, sedangkan angket menyelidiki lebih dalam." },
    { q: "Peraturan menteri yang diduga bertentangan dengan undang-undang dapat diuji ke ....", options: ["Mahkamah Konstitusi","Komisi Yudisial","Mahkamah Agung","BPK"], answer: 2, solution: "1. MA berwenang menguji peraturan perundang-undangan di bawah undang-undang terhadap undang-undang (hak uji materiil). 2. MK hanya menguji undang-undang terhadap UUD 1945. 3. Miskonsepsi umum: tidak semua pengujian ke MK — kalau yang diuji peraturan di bawah UU, larinya ke MA." },
    { q: "Lembaga negara yang berwenang memutus pembubaran partai politik adalah ....", options: ["Mahkamah Konstitusi","Mahkamah Agung","Komisi Yudisial","DPR"], answer: 0, solution: "1. MK berwenang memutus pembubaran partai politik. 2. MK juga memutus sengketa hasil pemilu dan sengketa kewenangan antarlembaga negara. 3. Jangan tertukar: MA mengadili perkara pada tingkat kasasi, bukan membubarkan partai politik." },
    { q: "Jika dua pasangan calon presiden bersengketa tentang hasil penghitungan suara pemilu, lembaga yang memutusnya adalah ....", options: ["Mahkamah Agung","Mahkamah Konstitusi","Bawaslu","KPU"], answer: 1, solution: "1. Perselisihan hasil pemilihan umum (PHPU) diputus oleh MK. 2. Bawaslu menangani pelanggaran administratif pemilu, bukan sengketa hasil. 3. Jangan tertukar: KPU menetapkan hasil pemilu, MK yang memutus sengketanya." },
    { q: "Komisi Yudisial (KY) memiliki wewenang ....", options: ["mengadili perkara pidana pada tingkat kasasi","menguji undang-undang terhadap UUD 1945","memeriksa laporan keuangan negara","menjaga kehormatan dan perilaku hakim serta mengusulkan pengangkatan hakim agung"], answer: 3, solution: "1. KY bersifat mandiri: mengusulkan pengangkatan hakim agung serta menjaga kehormatan dan perilaku hakim. 2. Mengadili kasasi adalah wewenang MA, menguji UU adalah wewenang MK, memeriksa keuangan adalah wewenang BPK. 3. Jangan tertukar: KY tidak mengadili perkara sama sekali." },
    { q: "BPK memeriksa pengelolaan dan tanggung jawab keuangan negara. Hasil pemeriksaan BPK diserahkan kepada ....", options: ["Presiden dan para menteri","Mahkamah Agung","DPR, DPD, dan DPRD","KPU"], answer: 2, solution: "1. Hasil pemeriksaan BPK diserahkan kepada DPR, DPD, dan DPRD sesuai dengan kewenangannya. 2. Tujuannya agar lembaga perwakilan rakyat dapat mengawasi penggunaan anggaran negara. 3. Jangan tertukar: BPK hanya memeriksa, bukan menghukum — itu wewenang pengadilan." },
    { q: "Gubernur, bupati, dan wali kota dipilih secara langsung oleh rakyat dalam ....", options: ["pilkada","pemilu legislatif","pemilihan ketua RT","musyawarah desa"], answer: 0, solution: "1. Pilkada adalah pemilihan kepala daerah (gubernur, bupati, wali kota) secara langsung oleh rakyat. 2. Ini wujud otonomi daerah: daerah mengatur dan mengurus urusannya sendiri. 3. Jangan tertukar: pemilu legislatif memilih anggota DPR dan DPRD, bukan kepala daerah." },
    { q: "DPRD memiliki tiga fungsi seperti DPR, yaitu legislasi, anggaran, dan pengawasan, tetapi lingkup kerjanya adalah ....", options: ["nasional (membuat undang-undang)","daerah (membuat perda dan membahas APBD)","internasional (hubungan luar negeri)","partai politik"], answer: 1, solution: "1. DPRD adalah lembaga legislatif daerah: membuat peraturan daerah (perda) dan membahas APBD. 2. DPR lingkupnya nasional, yaitu membuat undang-undang dan membahas APBN. 3. Jangan tertukar: DPD mewakili daerah di tingkat nasional, sedangkan DPRD bekerja di daerah." },
    { q: "Perbedaan utama antara DPR dan DPD adalah ....", options: ["DPR dipilih rakyat, DPD diangkat presiden","DPR di pusat, DPD di daerah","DPR 5 tahun, DPD 10 tahun masa jabatannya","anggota DPR dari partai politik, anggota DPD perseorangan mewakili provinsi"], answer: 3, solution: "1. DPR mewakili rakyat melalui partai politik, sedangkan DPD mewakili daerah atau provinsi dan dipilih secara perseorangan. 2. Keduanya sama-sama dipilih rakyat dengan masa jabatan 5 tahun. 3. Jangan tertukar: DPD berkedudukan di pusat seperti DPR, bukan di daerah." },
    { q: "Salah satu fungsi partai politik dalam kehidupan demokrasi adalah ....", options: ["menyelenggarakan pemungutan suara pemilu","mengadili sengketa hasil pemilu","sarana pendidikan politik dan rekrutmen calon pemimpin","mengawasi jalannya pemerintahan"], answer: 2, solution: "1. Partai politik menjadi sarana partisipasi masyarakat, pendidikan politik, dan rekrutmen calon pemimpin. 2. Menyelenggarakan pemilu adalah tugas KPU, mengadili sengketa hasil adalah tugas MK. 3. Miskonsepsi: partai politik bukan penyelenggara pemilu, melainkan pesertanya." },
    { q: "Kemerdekaan berserikat dan berkumpul serta mengeluarkan pikiran dengan lisan dan tulisan dijamin dalam UUD 1945 Pasal ....", options: ["28","27","29","30"], answer: 0, solution: "1. Pasal 28 UUD 1945 menjamin kemerdekaan berserikat, berkumpul, dan mengeluarkan pendapat. 2. Pasal 28E ayat (3) menegaskan setiap orang berhak atas kebebasan berserikat dan berkumpul. 3. Jangan tertukar: Pasal 27 tentang pekerjaan dan bela negara, Pasal 29 tentang agama." },
    { q: "Kebebasan pers di Indonesia dijamin oleh ....", options: ["UU No. 11 Tahun 2008 tentang ITE","UU No. 40 Tahun 1999 tentang Pers","UUD 1945 Pasal 27","KUHP"], answer: 1, solution: "1. UU No. 40 Tahun 1999 tentang Pers menjamin kemerdekaan pers di Indonesia. 2. Pers bebas memberitakan fakta tanpa sensor, tetapi tetap bertanggung jawab atas pemberitaannya. 3. Jangan tertukar: UU ITE mengatur informasi elektronik, bukan jaminan kebebasan pers." },
    { q: "Teori pemisahan kekuasaan negara menjadi legislatif, eksekutif, dan yudikatif dikemukakan oleh ....", options: ["John Locke","Aristoteles","Montesquieu","J.J. Rousseau"], answer: 2, solution: "1. Montesquieu mencetuskan teori Trias Politica: legislatif, eksekutif, dan yudikatif. 2. Tujuannya agar kekuasaan negara tidak menumpuk di satu tangan sehingga tidak disalahgunakan. 3. Jangan tertukar: Rousseau terkenal dengan teori kontrak sosial, bukan trias politica." },
    { q: "Di Indonesia, kekuasaan legislatif dijalankan oleh ....", options: ["MPR, DPR, dan DPD","Presiden dan para menteri","MA, MK, dan KY","KPU dan Bawaslu"], answer: 0, solution: "1. Kekuasaan legislatif adalah kekuasaan membuat undang-undang, dijalankan oleh MPR, DPR, dan DPD. 2. Eksekutif dijalankan presiden, yudikatif dijalankan MA, MK, dan KY. 3. Jangan tertukar: KPU dan Bawaslu adalah penyelenggara serta pengawas pemilu, bukan legislatif." },
    { q: "Indonesia menganut sistem demokrasi ....", options: ["langsung","liberal penuh","terpimpin","perwakilan (tidak langsung)"], answer: 3, solution: "1. Rakyat menyalurkan aspirasinya melalui wakil-wakil di DPR dan DPRD yang dipilih dalam pemilu. 2. Inilah yang disebut demokrasi perwakilan atau demokrasi tidak langsung. 3. Jangan tertukar: demokrasi langsung berarti rakyat memutuskan semuanya sendiri tanpa perantara wakil." },
    { q: "Masa jabatan anggota DPR, DPD, dan MPR adalah ....", options: ["5 tahun dan tidak dapat dipilih kembali","5 tahun dan dapat dipilih kembali","4 tahun dan dapat dipilih kembali","10 tahun sekali pemilihan"], answer: 1, solution: "1. Anggota DPR, DPD, dan MPR menjabat selama 5 tahun seiring dengan siklus pemilu. 2. Berbeda dengan presiden yang dibatasi maksimal 2 periode, anggota legislatif dapat dipilih kembali tanpa batasan periode. 3. Jangan tertukar dengan masa jabatan presiden yang maksimal 2 periode." },
    { q: "Prinsip 'checks and balances' dalam demokrasi berarti ....", options: ["presiden memegang seluruh kekuasaan negara","DPR tunduk sepenuhnya pada perintah presiden","lembaga-lembaga negara saling mengawasi dan mengimbangi","rakyat tidak boleh mengkritik pemerintah"], answer: 2, solution: "1. Checks and balances berarti kekuasaan saling mengontrol, misalnya DPR mengawasi presiden. 2. Tujuannya mencegah penyalahgunaan kekuasaan oleh satu lembaga. 3. Miskonsepsi: demokrasi justru memberi ruang kritik kepada rakyat, bukan melarangnya." },
    { q: "Contoh peran serta warga negara dalam kehidupan demokrasi di lingkungan sekolah adalah ....", options: ["mengikuti pemilihan ketua OSIS secara jujur dan adil","menolak semua keputusan hasil musyawarah kelas","memaksa teman memilih calon tertentu","tidak peduli siapa yang menjadi ketua kelas"], answer: 0, solution: "1. Ikut memilih dengan jujur dan adil adalah latihan berdemokrasi sejak dini. 2. Memaksa pilihan orang lain melanggar asas pemilu yang bebas dan rahasia. 3. Miskonsepsi: demokrasi bukan menolak semua keputusan, melainkan menghormati hasil musyawarah bersama." },
    { q: "BPUPKI (Badan Penyelidik Usaha-Usaha Persiapan Kemerdekaan Indonesia) dibentuk oleh pemerintah Jepang pada tanggal ....", options: ["29 April 1945","7 Agustus 1945","1 Juni 1945","22 Juni 1945"], answer: 0, solution: "1. BPUPKI dibentuk pada 29 April 1945. 2. Tanggal 7 Agustus 1945 adalah pembentukan PPKI, sedangkan 1 Juni 1945 adalah hari lahir Pancasila. 3. Jangan tertukar: BPUPKI (April) bertugas menyelidiki dan menyiapkan, PPKI (Agustus) bertugas mengesahkan." },
    { q: "Ketua BPUPKI adalah ....", options: ["Ir. Soekarno","Drs. Moh. Hatta","Mr. Soepomo","dr. KRT Radjiman Wedyodiningrat"], answer: 3, solution: "1. Ketua BPUPKI adalah dr. KRT Radjiman Wedyodiningrat. 2. Ir. Soekarno adalah ketua PPKI, bukan BPUPKI. 3. Miskonsepsi umum: karena Soekarno tokoh utama kemerdekaan, banyak yang mengira ia memimpin BPUPKI." },
    { q: "Sidang pertama BPUPKI yang berlangsung pada 29 Mei-1 Juni 1945 membahas tentang ....", options: ["dasar negara Indonesia","rancangan Undang-Undang Dasar","Piagam Jakarta","pengesahan UUD 1945"], answer: 0, solution: "1. Sidang pertama BPUPKI membahas dasar negara, yang melahirkan Pancasila pada 1 Juni 1945. 2. Rancangan UUD baru dibahas pada sidang kedua BPUPKI (10-17 Juli 1945). 3. Jangan tertukar: sidang I = dasar negara, sidang II = rancangan UUD." },
    { q: "Sidang kedua BPUPKI yang berlangsung pada 10-17 Juli 1945 membahas tentang ....", options: ["dasar negara Indonesia","rancangan Undang-Undang Dasar","pemilihan presiden pertama","pembubaran BPUPKI"], answer: 1, solution: "1. Sidang kedua BPUPKI membahas rancangan Undang-Undang Dasar. 2. Dalam sidang ini dibentuk Panitia Perancang UUD yang diketuai Ir. Soekarno. 3. Kebalikannya sering tertukar: sidang pertama justru membahas dasar negara, bukan rancangan UUD." },
    { q: "Piagam Jakarta disahkan oleh Panitia Sembilan pada tanggal ....", options: ["1 Juni 1945","22 Juni 1945","17 Agustus 1945","18 Agustus 1945"], answer: 1, solution: "1. Piagam Jakarta disahkan pada 22 Juni 1945 oleh Panitia Sembilan. 2. Tanggal 1 Juni 1945 adalah pidato Soekarno tentang Pancasila, bukan Piagam Jakarta. 3. Piagam Jakarta kemudian menjadi cikal bakal Pembukaan UUD 1945." },
    { q: "Atas usulan Moh. Hatta, tujuh kata dalam sila pertama Piagam Jakarta diubah sehingga berbunyi ....", options: ["Ketuhanan Yang Maha Esa","Ketuhanan dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya","Kemanusiaan yang adil dan beradab","Persatuan Indonesia"], answer: 0, solution: "1. Tujuh kata 'dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya' dihapus atas usulan Hatta. 2. Sila pertama menjadi 'Ketuhanan Yang Maha Esa' agar dapat diterima seluruh rakyat Indonesia. 3. Jangan terbalik: bunyi yang panjang justru bunyi awal yang kemudian diubah." },
    { q: "PPKI (Panitia Persiapan Kemerdekaan Indonesia) dibentuk pada tanggal 7 Agustus 1945 dengan ketua ....", options: ["dr. KRT Radjiman Wedyodiningrat","Ir. Soekarno","Drs. Moh. Hatta","Mr. Soepomo"], answer: 1, solution: "1. PPKI dibentuk 7 Agustus 1945, diketuai Ir. Soekarno dengan wakil Drs. Moh. Hatta. 2. Radjiman Wedyodiningrat adalah ketua BPUPKI, bukan PPKI. 3. Ingat polanya: BPUPKI = menyelidiki dan menyiapkan (Radjiman), PPKI = mempersiapkan dan mengesahkan (Soekarno)." },
    { q: "Berikut ini yang BUKAN hasil sidang PPKI pada tanggal 18 Agustus 1945 adalah ....", options: ["Mengesahkan UUD 1945","Memilih Ir. Soekarno dan Drs. Moh. Hatta sebagai presiden dan wakil presiden","Presiden untuk sementara dibantu oleh Komite Nasional","Membagi wilayah Indonesia menjadi 8 provinsi"], answer: 3, solution: "1. Hasil sidang 18 Agustus 1945: mengesahkan UUD 1945, memilih presiden dan wakil presiden, serta presiden untuk sementara dibantu Komite Nasional. 2. Pembagian wilayah menjadi 8 provinsi adalah hasil sidang PPKI tanggal 19 Agustus 1945. 3. Hati-hati dengan sidang yang berurutan: 18, 19, dan 22 Agustus 1945." },
    { q: "Dekret Presiden yang dikeluarkan pada tanggal 5 Juli 1959 menetapkan ....", options: ["pembubaran BPUPKI","perubahan pertama UUD 1945","berlakunya kembali UUD 1945","pembentukan PPKI"], answer: 2, solution: "1. Dekret Presiden 5 Juli 1959 menetapkan berlakunya kembali UUD 1945 dan pembubaran Konstituante. 2. Dekret ini mengakhiri masa berlakunya UUDS 1950. 3. Jangan dikira dekret ini mengubah UUD 1945 - isinya justru mengembalikan berlakunya UUD 1945." },
    { q: "Batang Tubuh UUD 1945 terdiri atas ....", options: ["16 bab dan 37 pasal","4 alinea","37 bab dan 16 pasal","20 bab dan 45 pasal"], answer: 0, solution: "1. Batang Tubuh UUD 1945 terdiri atas 16 bab dan 37 pasal. 2. Yang terdiri atas 4 alinea adalah Pembukaan UUD 1945, bukan Batang Tubuh. 3. Miskonsepsi umum: menukar jumlah bab dan pasal, atau mencampuradukkan Pembukaan dengan Batang Tubuh." },
    { q: "Cita-cita bangsa Indonesia yang 'merdeka, bersatu, berdaulat, adil dan makmur' tercantum dalam Pembukaan UUD 1945 alinea ....", options: ["pertama","ketiga","kedua","keempat"], answer: 2, solution: "1. Alinea kedua memuat perjuangan pergerakan kemerdekaan dan cita-cita bangsa yang merdeka, bersatu, berdaulat, adil dan makmur. 2. Alinea pertama berisi pernyataan bahwa penjajahan di atas dunia harus dihapuskan. 3. Banyak yang menebak alinea pertama, padahal cita-cita bangsa tercantum di alinea kedua." },
    { q: "Pernyataan kemerdekaan bangsa Indonesia yang diawali kalimat 'Atas berkat rahmat Allah Yang Maha Kuasa ...' terdapat dalam Pembukaan UUD 1945 alinea ....", options: ["pertama","kedua","keempat","ketiga"], answer: 3, solution: "1. Alinea ketiga berisi pernyataan kemerdekaan atas berkat rahmat Allah Yang Maha Kuasa. 2. Alinea ketiga merupakan pernyataan kemerdekaan yang singkat dan padat. 3. Jangan tertukar dengan alinea keempat yang memuat tujuan negara dan dasar negara." },
    { q: "Dalam empat kali amandemen UUD 1945, bagian yang disepakati untuk TIDAK diubah adalah ....", options: ["Batang Tubuh","Pembukaan","Aturan Peralihan","Aturan Tambahan"], answer: 1, solution: "1. Salah satu kesepakatan dasar amandemen adalah tidak mengubah Pembukaan UUD 1945. 2. Perubahan hanya dilakukan pada Batang Tubuh serta aturan peralihan dan aturan tambahan. 3. Miskonsepsi: mengira amandemen mengubah seluruh UUD termasuk Pembukaan." },
    { q: "Amandemen pertama UUD 1945 dilakukan pada tahun ....", options: ["1999","2000","2001","2002"], answer: 0, solution: "1. Amandemen pertama dilakukan pada 19 Oktober 1999. 2. Urutan amandemen: pertama 1999, kedua 2000, ketiga 2001, keempat 2002. 3. Cara mengingat: empat amandemen dalam empat tahun berturut-turut, dimulai tahun 1999." },
    { q: "Amandemen keempat sekaligus terakhir UUD 1945 dilakukan pada tahun ....", options: ["1999","2000","2001","2002"], answer: 3, solution: "1. Amandemen keempat dilakukan pada 10 Agustus 2002. 2. Setelah amandemen keempat, Batang Tubuh UUD 1945 terdiri atas 16 bab, 37 pasal, dan 170 ayat. 3. Jangan tertukar dengan amandemen pertama (1999) yang antara lain membatasi masa jabatan presiden." },
    { q: "Lembaga negara berikut ini yang dibentuk berdasarkan hasil amandemen UUD 1945 adalah ....", options: ["MPR","DPR","Mahkamah Agung","Dewan Perwakilan Daerah (DPD)"], answer: 3, solution: "1. DPD dibentuk melalui amandemen (perubahan ketiga, 2001) dan anggotanya pertama kali dipilih pada Pemilu 2004. 2. MPR, DPR, dan Mahkamah Agung sudah ada sejak UUD 1945 disahkan. 3. Selain DPD, lembaga baru hasil amandemen antara lain Mahkamah Konstitusi dan Komisi Yudisial." },
    { q: "Setelah amandemen UUD 1945, kedudukan MPR adalah ....", options: ["lembaga tertinggi negara","lembaga tertinggi di atas presiden","bawahan presiden","sama dan sederajat dengan lembaga negara lainnya"], answer: 3, solution: "1. Setelah amandemen, tidak ada lagi lembaga tertinggi negara; semua lembaga negara berkedudukan sederajat. 2. Sebelum amandemen, MPR memang berkedudukan sebagai lembaga tertinggi negara. 3. Miskonsepsi umum: masih menganggap MPR sebagai lembaga tertinggi seperti sebelum amandemen." },
    { q: "Pasal 27 ayat (1) UUD 1945 menegaskan bahwa segala warga negara bersamaan kedudukannya dalam hukum dan pemerintahan serta wajib ....", options: ["membayar pajak","mengikuti pendidikan dasar","menjunjung hukum dan pemerintahan","ikut serta dalam pembelaan negara"], answer: 2, solution: "1. Pasal 27 ayat (1): segala warga negara bersamaan kedudukannya dalam hukum dan pemerintahan dan wajib menjunjung hukum dan pemerintahan itu. 2. Artinya tidak ada warga negara yang kebal hukum. 3. Jangan tertukar dengan ayat (2) yang mengatur hak atas pekerjaan dan penghidupan yang layak." },
    { q: "Hak setiap orang untuk berkomunikasi dan memperoleh informasi dijamin dalam UUD 1945 ....", options: ["Pasal 28F","Pasal 28E","Pasal 28G","Pasal 28H"], answer: 0, solution: "1. Pasal 28F menjamin hak untuk berkomunikasi dan memperoleh informasi. 2. Pasal 28E mengatur kebebasan memeluk agama, berkeyakinan, dan menyatakan pikiran. 3. Pasal-pasal 28 yang berurutan memang membingungkan; ingat F = informasi (komunikasi)." },
    { q: "Hak asasi manusia yang TIDAK dapat dikurangi dalam keadaan apa pun, seperti hak untuk hidup dan hak untuk tidak disiksa, diatur dalam ....", options: ["Pasal 28H","Pasal 28J","Pasal 29","Pasal 28I"], answer: 3, solution: "1. Pasal 28I ayat (1) menegaskan hak-hak yang tidak dapat dikurangi dalam keadaan apa pun. 2. Contohnya: hak untuk hidup, tidak disiksa, kebebasan beragama, dan tidak diperbudak. 3. Pasal 28J justru mengatur pembatasannya - kebalikannya, jadi jangan tertukar." },
    { q: "Menurut Pasal 28J UUD 1945, dalam menjalankan hak dan kebebasannya setiap orang wajib tunduk pada pembatasan yang ditetapkan dengan undang-undang dengan maksud ....", options: ["menghapus hak asasi manusia","memberi kekuasaan mutlak kepada negara","menjamin pengakuan dan penghormatan atas hak orang lain","membatasi kebebasan beragama sepenuhnya"], answer: 2, solution: "1. Pembatasan bertujuan menjamin pengakuan serta penghormatan atas hak dan kebebasan orang lain. 2. Pembatasan juga untuk memenuhi tuntutan yang adil sesuai pertimbangan moral, nilai agama, keamanan, dan ketertiban umum. 3. Miskonsepsi: mengira HAM bersifat mutlak tanpa batas - padahal kebebasan seseorang dibatasi oleh hak orang lain." },
    { q: "Ketentuan bahwa 'Negara berdasar atas Ketuhanan Yang Maha Esa' tercantum dalam UUD 1945 ....", options: ["Pasal 28E ayat (1)","Pasal 29 ayat (1)","Pasal 29 ayat (2)","Pasal 31 ayat (1)"], answer: 1, solution: "1. Pasal 29 ayat (1) menyatakan negara berdasar atas Ketuhanan Yang Maha Esa. 2. Pasal 29 ayat (2) menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agama dan beribadat. 3. Jangan tertukar: ayat (1) = dasar negara, ayat (2) = jaminan kebebasan beragama." },
    { q: "Menurut Pasal 30 ayat (2) UUD 1945, usaha pertahanan dan keamanan negara dilaksanakan melalui sistem pertahanan dan keamanan rakyat semesta dengan kekuatan utama ....", options: ["TNI dan Kepolisian sebagai kekuatan utama","rakyat sebagai kekuatan utama","MPR sebagai kekuatan utama","pemerintah daerah sebagai kekuatan utama"], answer: 0, solution: "1. TNI dan Kepolisian adalah kekuatan utama, sedangkan rakyat sebagai kekuatan pendukung. 2. Inilah yang disebut sistem pertahanan dan keamanan rakyat semesta (sishankamrata). 3. Miskonsepsi: mengira rakyat adalah kekuatan utama - padahal rakyat adalah kekuatan pendukung." },
    { q: "Menurut Pasal 31 ayat (2) UUD 1945, setiap warga negara wajib mengikuti pendidikan dasar dan ....", options: ["pemerintah wajib membiayainya","orang tua wajib membayar penuh","sekolah swasta wajib gratis","pemerintah daerah wajib menanggung separuhnya"], answer: 0, solution: "1. Pasal 31 ayat (2): setiap warga negara wajib mengikuti pendidikan dasar dan pemerintah wajib membiayainya. 2. Inilah dasar hukum program wajib belajar pendidikan dasar. 3. Jangan dikira biaya ditanggung orang tua - UUD menegaskan pemerintah yang wajib membiayai." },
    { q: "UUD 1945 Pasal 31 ayat (4) mewajibkan negara memprioritaskan anggaran pendidikan sekurang-kurangnya ....", options: ["10% dari APBN dan APBD","20% dari APBN dan APBD","15% dari APBN dan APBD","25% dari APBN dan APBD"], answer: 1, solution: "1. Negara memprioritaskan anggaran pendidikan sekurang-kurangnya 20% dari APBN serta APBD. 2. Ketentuan ini menjamin terpenuhinya kebutuhan penyelenggaraan pendidikan nasional. 3. Angka 20% sering tertukar dengan angka lain - ingat: dua puluh persen." },
    { q: "Menurut Pasal 33 ayat (1) UUD 1945, perekonomian Indonesia disusun sebagai usaha bersama berdasar atas asas ....", options: ["kebebasan","persaingan","individualisme","kekeluargaan"], answer: 3, solution: "1. Perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan. 2. Asas kekeluargaan menolak paham individualisme dan persaingan bebas dalam ekonomi. 3. Miskonsepsi: mengira ekonomi Indonesia menganut asas persaingan bebas." },
    { q: "'Bumi dan air dan kekayaan alam yang terkandung di dalamnya dikuasai oleh negara dan dipergunakan untuk sebesar-besar kemakmuran rakyat' merupakan bunyi UUD 1945 ....", options: ["Pasal 33 ayat (1)","Pasal 33 ayat (3)","Pasal 33 ayat (2)","Pasal 34 ayat (1)"], answer: 1, solution: "1. Ketentuan tersebut adalah bunyi Pasal 33 ayat (3). 2. Ayat (2) mengatur cabang produksi yang penting dikuasai negara, sedangkan ayat (3) mengatur bumi, air, dan kekayaan alam. 3. Perhatikan katanya: 'dikuasai' negara, bukan 'dimiliki' - dan untuk sebesar-besar kemakmuran rakyat." },
    { q: "Menurut Pasal 34 ayat (1) UUD 1945, fakir miskin dan anak-anak yang terlantar ....", options: ["diberi pekerjaan oleh negara","dipelihara oleh negara","dipulangkan ke daerah asal","diserahkan kepada keluarga"], answer: 1, solution: "1. Pasal 34 ayat (1): fakir miskin dan anak-anak yang terlantar dipelihara oleh negara. 2. Ini adalah wujud tanggung jawab negara dalam mewujudkan keadilan sosial. 3. Kata kuncinya 'dipelihara oleh negara' - bukan sekadar diberi pekerjaan." },
    { q: "Menurut Pasal 18 ayat (4) UUD 1945, gubernur, bupati, dan walikota sebagai kepala pemerintah daerah ....", options: ["diangkat oleh presiden","ditunjuk oleh DPRD","dipilih secara demokratis","dipilih oleh MPR"], answer: 2, solution: "1. Gubernur, bupati, dan walikota dipilih secara demokratis. 2. Sebelum amandemen, kepala daerah dipilih oleh DPRD. 3. Miskonsepsi: masih mengira kepala daerah dipilih DPRD seperti sebelum amandemen." },
    { q: "Menurut Pasal 18 ayat (5) UUD 1945, pemerintahan daerah menjalankan otonomi seluas-luasnya, KECUALI ....", options: ["urusan pemerintahan yang ditentukan sebagai urusan Pemerintah Pusat","urusan pendidikan dan kesehatan","urusan pembangunan daerah","urusan pelayanan masyarakat"], answer: 0, solution: "1. Otonomi seluas-luasnya dikecualikan untuk urusan pemerintahan yang oleh undang-undang ditentukan sebagai urusan Pemerintah Pusat. 2. Contoh urusan pusat: politik luar negeri, pertahanan, keamanan, yustisi, moneter dan fiskal nasional, serta agama. 3. Miskonsepsi: otonomi daerah disamakan dengan merdeka atau berdiri sendiri - padahal Indonesia tetap negara kesatuan." },
    { q: "Dalam melaksanakan fungsinya, DPR memiliki hak interpelasi, hak angket, dan hak menyatakan pendapat. Hak angket adalah hak DPR untuk ....", options: ["meminta keterangan kepada pemerintah tentang kebijakan penting","menyetujui anggaran negara","mengajukan rancangan undang-undang","melakukan penyelidikan terhadap pelaksanaan suatu undang-undang"], answer: 3, solution: "1. Hak angket adalah hak DPR melakukan penyelidikan terhadap pelaksanaan suatu undang-undang atau kebijakan pemerintah. 2. Hak interpelasi adalah hak meminta keterangan kepada pemerintah. 3. Keduanya sering tertukar: interpelasi = bertanya/meminta keterangan, angket = menyelidiki." },
    { q: "Menguji peraturan perundang-undangan di bawah undang-undang terhadap undang-undang merupakan wewenang ....", options: ["Mahkamah Agung","Mahkamah Konstitusi","Komisi Yudisial","Dewan Perwakilan Rakyat"], answer: 0, solution: "1. Mahkamah Agung berwenang menguji peraturan di bawah undang-undang terhadap undang-undang (Pasal 24A). 2. Mahkamah Konstitusi menguji undang-undang terhadap UUD. 3. Cara mengingat: MK menguji UU terhadap UUD (tingkat lebih tinggi), MA menguji peraturan di bawah UU terhadap UU (tingkat lebih rendah)." },
    { q: "Komisi Yudisial (KY) memiliki wewenang untuk ....", options: ["mengadili perkara pidana","menetapkan undang-undang","mengusulkan pengangkatan hakim agung","memeriksa keuangan negara"], answer: 2, solution: "1. Komisi Yudisial berwenang mengusulkan pengangkatan hakim agung serta menjaga kehormatan, keluhuran martabat, dan perilaku hakim. 2. KY tidak mengadili perkara - itu tugas Mahkamah Agung. 3. Miskonsepsi: mengira KY adalah pengadilan, padahal ia pengawas kehormatan hakim." },
    { q: "Badan Pemeriksa Keuangan (BPK) bertugas ....", options: ["menyusun anggaran pendapatan dan belanja negara","memeriksa pengelolaan dan tanggung jawab keuangan negara","menetapkan pajak negara","mengawasi jalannya pemerintahan daerah"], answer: 1, solution: "1. BPK memeriksa pengelolaan dan tanggung jawab tentang keuangan negara (Pasal 23E). 2. Hasil pemeriksaan BPK diserahkan kepada DPR, DPD, dan DPRD sesuai kewenangannya. 3. Miskonsepsi: mengira BPK yang menyusun APBN - padahal APBN ditetapkan dengan undang-undang atas persetujuan DPR." },
    { q: "Jumlah anggota DPD dari setiap provinsi adalah ....", options: ["sama, yaitu 4 orang","sesuai jumlah penduduk provinsi","ditentukan oleh presiden","sama dengan jumlah anggota DPR"], answer: 0, solution: "1. Anggota DPD dari setiap provinsi jumlahnya sama, yaitu 4 orang, dan dipilih melalui pemilihan umum. 2. Anggota DPD berasal dari perseorangan, bukan dari partai politik. 3. Miskonsepsi: mengira jumlah anggota DPD proporsional seperti DPR - padahal setiap provinsi sama." },
    { q: "Menurut Pasal 5 ayat (1) UUD 1945, presiden berhak ....", options: ["menetapkan UUD","membubarkan DPR","mengubah undang-undang","mengajukan rancangan undang-undang kepada DPR"], answer: 3, solution: "1. Presiden berhak mengajukan rancangan undang-undang kepada DPR. 2. RUU kemudian dibahas dan disetujui bersama oleh DPR dan presiden. 3. Miskonsepsi: mengira presiden dapat menetapkan UU sendiri - padahal kekuasaan membentuk UU ada pada DPR dengan persetujuan bersama presiden." },
    { q: "Pasangan calon presiden dan wakil presiden dilantik apabila memperoleh suara lebih dari 50% dengan sedikitnya 20% suara di setiap provinsi yang tersebar di ....", options: ["seluruh provinsi di Indonesia","seperempat jumlah provinsi di Indonesia","lebih dari setengah jumlah provinsi di Indonesia","tiga provinsi terbesar di Indonesia"], answer: 2, solution: "1. Syaratnya: lebih dari 50% suara sah dengan sedikitnya 20% suara di setiap provinsi yang tersebar di lebih dari setengah jumlah provinsi. 2. Ketentuan ini tercantum dalam Pasal 6A ayat (3) hasil amandemen. 3. Tujuannya agar presiden terpilih memperoleh dukungan yang merata di seluruh Indonesia." },
    { q: "Sistem pemerintahan Indonesia menurut UUD 1945 adalah sistem presidensial, yang berarti ....", options: ["presiden hanya sebagai kepala negara","presiden sebagai kepala negara sekaligus kepala pemerintahan","perdana menteri memegang pemerintahan","MPR memegang kekuasaan pemerintahan"], answer: 1, solution: "1. Dalam sistem presidensial, presiden berkedudukan sebagai kepala negara sekaligus kepala pemerintahan. 2. Presiden memegang kekuasaan pemerintahan menurut UUD (Pasal 4 ayat 1). 3. Miskonsepsi: mengira Indonesia menganut sistem parlementer yang dipimpin perdana menteri." },
    { q: "Lembaga negara yang bertugas melakukan pengkajian, penelitian, penyuluhan, pemantauan, dan mediasi masalah hak asasi manusia di Indonesia adalah ....", options: ["Komnas HAM", "Komisi Yudisial", "KPK", "Mahkamah Konstitusi"], answer: 0, solution: "1. Komnas HAM (Komisi Nasional Hak Asasi Manusia) adalah lembaga mandiri yang khusus menangani masalah HAM. 2. KPK memberantas korupsi, Komisi Yudisial menjaga kehormatan hakim, MK menguji undang-undang — bukan urusan HAM. 3. Jangan tertukar dengan LPSK: LPSK melindungi saksi dan korban, bukan memediasi pelanggaran HAM." },
    { q: "Payung hukum utama perlindungan hak asasi manusia di Indonesia adalah ....", options: ["UU No. 5 Tahun 1998", "UU No. 26 Tahun 2000", "UU No. 39 Tahun 1999", "UU No. 23 Tahun 2002"], answer: 2, solution: "1. UU No. 39 Tahun 1999 adalah Undang-Undang tentang Hak Asasi Manusia. 2. UU 26/2000 mengatur Pengadilan HAM dan UU 23/2002 tentang Perlindungan Anak — keduanya aturan khusus, bukan payung utama. 3. Jangan hafal nomornya saja: pahami isi undang-undangnya, karena nomor mudah tertukar saat ujian." },
    { q: "Di sekolah, Andi selalu menghargai pendapat teman saat diskusi kelompok dan tidak pernah mengejek teman yang berbeda suku. Sikap Andi menunjukkan penghormatan terhadap HAM karena ....", options: ["ia ingin mendapat nilai bagus", "ia takut dimarahi guru", "setiap orang berhak atas penghormatan martabat dan kebebasan berpendapat", "ia hanya mengikuti perintah orang tuanya"], answer: 2, solution: "1. HAM menjamin setiap orang dihormati martabatnya dan bebas berpendapat. 2. Menghargai pendapat dan tidak mendiskriminasi adalah wujud nyata penghormatan HAM. 3. Ini bukan sekadar sopan santun biasa: di baliknya ada hak asasi yang dilindungi hukum." },
    { q: "Contoh sikap menghormati HAM dalam kehidupan keluarga adalah ....", options: ["orang tua memaksa anak memilih jurusan tanpa diskusi", "kakak melarang adik bermain agar rumah sepi", "ayah mendengarkan pendapat anak sebelum mengambil keputusan keluarga", "ibu menyita seluruh uang jajan sebagai hukuman"], answer: 2, solution: "1. Setiap anggota keluarga berhak didengar pendapatnya. 2. Musyawarah sebelum mengambil keputusan menghormati hak seluruh anggota keluarga. 3. Kasih sayang bukan berarti boleh semena-mena: memaksa tanpa diskusi melanggar hak anak untuk berpendapat." },
    { q: "Deklarasi yang menjadi tonggak penegakan HAM di dunia dan disahkan PBB pada 10 Desember 1948 adalah ....", options: ["Piagam PBB", "Deklarasi Universal Hak Asasi Manusia", "Konvensi Jenewa", "Statuta Roma"], answer: 1, solution: "1. Deklarasi Universal Hak Asasi Manusia (DUHAM) disahkan Majelis Umum PBB pada 10 Desember 1948. 2. Piagam PBB (1945) adalah piagam pendirian PBB, sedangkan Konvensi Jenewa mengatur hukum perang. 3. Tanggal 10 Desember diperingati sebagai Hari HAM Internasional — jangan tertukar dengan tanggal lain." },
    { q: "Pelanggaran HAM berat di Indonesia diadili melalui ....", options: ["Pengadilan Militer", "Pengadilan Tata Usaha Negara", "Pengadilan Agama", "Pengadilan HAM"], answer: 3, solution: "1. UU No. 26 Tahun 2000 membentuk Pengadilan HAM khusus untuk mengadili pelanggaran HAM berat. 2. Pengadilan militer mengadili prajurit TNI, pengadilan TUN menangani sengketa administrasi negara — bukan HAM. 3. Untuk peristiwa tertentu dapat dibentuk Pengadilan HAM ad hoc, misalnya untuk pelanggaran HAM berat masa lalu." },
    { q: "Salah satu peran Indonesia dalam penegakan HAM di tingkat dunia adalah ....", options: ["menjadi anggota Dewan HAM PBB", "membentuk pakta pertahanan militer", "menolak semua konvensi internasional", "menutup diri dari pergaulan dunia"], answer: 0, solution: "1. Indonesia aktif menjadi anggota Dewan HAM PBB dan meratifikasi berbagai konvensi HAM internasional. 2. Penegakan HAM di dunia ditempuh lewat diplomasi dan hukum internasional, bukan kekuatan militer. 3. Jangan tertukar dengan politik luar negeri bebas aktif: bebas aktif bukan berarti menolak kerja sama internasional." },
    { q: "Tindakan berikut yang MELANGGAR hak asasi teman di sekolah adalah ....", options: ["menolong teman yang jatuh", "melakukan perundungan (bullying) terhadap teman", "mengajak teman belajar kelompok", "menjenguk teman yang sakit"], answer: 1, solution: "1. Bullying merampas hak korban atas rasa aman, martabat, dan pendidikan. 2. Tiga pilihan lain justru wujud penghormatan terhadap HAM. 3. Bercanda yang menyakiti bukan sekadar kenakalan: jika merendahkan martabat orang lain, itu pelanggaran HAM." },
    { q: "Pasal 27 ayat (3) UUD 1945 menegaskan bahwa ikut serta dalam upaya pembelaan negara merupakan ....", options: ["hak sekaligus kewajiban setiap warga negara", "kewajiban TNI dan Polri saja", "hak yang boleh diabaikan warga sipil", "tugas pemerintah pusat semata"], answer: 0, solution: "1. Rumusan pasalnya berbunyi berhak dan wajib — artinya hak sekaligus kewajiban. 2. Bela negara bukan monopoli TNI dan Polri, melainkan milik seluruh warga negara. 3. Kesalahan umum: mengira bela negara hanya urusan tentara, padahal pelajar pun ikut serta lewat belajar dan disiplin." },
    { q: "Menurut Pasal 30 ayat (2) UUD 1945, usaha pertahanan dan keamanan negara dilaksanakan melalui ....", options: ["sistem pertahanan militer penuh", "sistem keamanan swasta", "sistem pertahanan negara sekutu", "sistem pertahanan dan keamanan rakyat semesta"], answer: 3, solution: "1. Pasal 30 ayat (2) menyebut sistem pertahanan dan keamanan rakyat semesta (sishankamrata). 2. Sistem ini melibatkan TNI, Polri, dan seluruh rakyat — bukan hanya militer. 3. Jangan tertukar: kata rakyat semesta artinya seluruh rakyat dilibatkan, bukan hanya aparat keamanan." },
    { q: "Dalam sistem pertahanan negara, yang berkedudukan sebagai komponen utama adalah ....", options: ["Tentara Nasional Indonesia", "Kepolisian Negara RI", "warga negara terlatih", "satuan pengamanan swasta"], answer: 0, solution: "1. UU No. 3 Tahun 2002 dan UU No. 23 Tahun 2019 menegaskan TNI sebagai komponen utama pertahanan negara. 2. Polri adalah kekuatan utama di bidang keamanan, bukan komponen utama pertahanan. 3. Komponen cadangan dan pendukung justru memperkuat komponen utama — jangan dibalik urutannya." },
    { q: "Tugas pokok TNI menurut Pasal 30 ayat (3) UUD 1945 adalah ....", options: ["mempertahankan, melindungi, dan memelihara keutuhan dan kedaulatan negara", "memelihara keamanan dan ketertiban masyarakat", "menegakkan hukum dan melayani masyarakat", "mengatur lalu lintas dan patroli kota"], answer: 0, solution: "1. Pasal 30 ayat (3) memberi TNI tugas mempertahankan keutuhan dan kedaulatan negara. 2. Menjaga kamtibmas dan melayani masyarakat adalah tugas Polri, bukan TNI. 3. Kunci membedakan: TNI menghadapi ancaman terhadap negara, Polri menjaga keamanan dan ketertiban masyarakat." },
    { q: "Menjaga kedaulatan dan menegakkan hukum di wilayah perairan Indonesia merupakan tugas pokok ....", options: ["TNI Angkatan Darat", "TNI Angkatan Laut", "TNI Angkatan Udara", "Polri"], answer: 1, solution: "1. TNI AL bertugas di matra laut, termasuk menjaga perairan yurisdiksi nasional. 2. AD menjaga matra darat dan AU menjaga matra udara. 3. Hafalkan pasangannya: AD–darat, AL–laut, AU–udara — jangan tertukar saat ujian." },
    { q: "Pengawasan dan pengamanan wilayah udara nasional dari pelanggaran kedaulatan menjadi tugas ....", options: ["TNI Angkatan Darat", "TNI Angkatan Laut", "TNI Angkatan Udara", "Badan SAR Nasional"], answer: 2, solution: "1. TNI AU bertanggung jawab atas matra udara Indonesia. 2. Pesawat asing yang melanggar wilayah udara nasional dihadapi oleh TNI AU. 3. BASARNAS bertugas dalam pencarian dan pertolongan, bukan pertahanan udara." },
    { q: "Satuan TNI yang bertugas mempertahankan keutuhan wilayah darat NKRI adalah ....", options: ["TNI Angkatan Laut", "TNI Angkatan Udara", "TNI Angkatan Darat", "Korps Marinir"], answer: 2, solution: "1. TNI AD adalah matra darat: menjaga perbatasan darat dan keutuhan wilayah darat. 2. Korps Marinir adalah bagian dari TNI AL — jangan terkecoh. 3. Ingat rumusnya: darat = AD, laut = AL, udara = AU." },
    { q: "Menurut UUD 1945 Pasal 10, pemegang kekuasaan tertinggi atas Angkatan Darat, Angkatan Laut, dan Angkatan Udara adalah ....", options: ["Presiden", "Panglima TNI", "Menteri Pertahanan", "DPR"], answer: 0, solution: "1. Pasal 10 UUD 1945 menegaskan Presiden memegang kekuasaan tertinggi atas ketiga angkatan. 2. Panglima TNI dan Menteri Pertahanan menjalankan komando di bawah Presiden. 3. Jangan tertukar: DPR memang punya fungsi pengawasan, tetapi bukan pemegang kekuasaan tertinggi atas angkatan bersenjata." },
    { q: "Komponen cadangan dalam sistem pertahanan negara terdiri atas ....", options: ["TNI yang sedang bertugas aktif", "sumber daya nasional yang disiapkan untuk memperkuat komponen utama", "senjata milik negara sahabat", "pasukan asing sekutu Indonesia"], answer: 1, solution: "1. Komponen cadangan adalah sumber daya nasional (SDM, SDA, sarana prasarana) yang disiapkan dan dilatih untuk memperkuat TNI. 2. TNI yang aktif justru komponen utama, bukan cadangan. 3. Komponen cadangan bukan tentara bayaran asing — mereka warga negara Indonesia yang disiapkan." },
    { q: "Warga negara, sumber daya alam, dan sarana prasarana nasional yang dapat digunakan untuk meningkatkan kekuatan pertahanan termasuk dalam ....", options: ["komponen utama", "komponen cadangan", "komponen pendukung", "komponen inti"], answer: 2, solution: "1. UU No. 23 Tahun 2019 membagi: utama = TNI, cadangan = yang disiapkan untuk dikerahkan, pendukung = sumber daya peningkat kekuatan. 2. Komponen pendukung memperkuat komponen utama dan komponen cadangan. 3. Jangan tertukar: disiapkan untuk dikerahkan = cadangan, dapat digunakan untuk meningkatkan kekuatan = pendukung." },
    { q: "Sishankamrata adalah singkatan dari ....", options: ["Sistem Pertahanan Militer Semesta", "Sistem Keamanan Nasional Terpadu", "Sistem Pertahanan dan Keamanan Rakyat Semesta", "Sistem Hankam Negara Kesatuan"], answer: 2, solution: "1. Sishankamrata = Sistem Pertahanan dan Keamanan Rakyat Semesta. 2. Kata kuncinya adalah rakyat semesta — seluruh rakyat dilibatkan dalam pertahanan negara. 3. Jangan sampai salah urut kata: pertahanan dan keamanan, bukan keamanan dan pertahanan." },
    { q: "Rina menolak ajakan tawuran, rajin belajar, dan menaati tata tertib sekolah. Sikap Rina merupakan wujud bela negara karena ....", options: ["ia takut dikeluarkan dari sekolah", "pelajar membela negara dengan menyiapkan diri menjadi generasi berkualitas", "tawuran dilarang polisi", "belajar hanya untuk nilai rapor"], answer: 1, solution: "1. Bela negara bagi pelajar adalah menyiapkan diri: disiplin, berprestasi, dan berakhlak mulia. 2. Generasi berkualitas adalah benteng negara di masa depan. 3. Bela negara tidak selalu berarti angkat senjata — bagi pelajar, senjata utamanya adalah ilmu dan disiplin." },
    { q: "Berikut ini yang termasuk ancaman militer terhadap NKRI adalah ....", options: ["peredaran narkoba", "korupsi pejabat negara", "kejahatan siber", "agresi militer negara asing"], answer: 3, solution: "1. Agresi atau invasi bersenjata dari negara asing adalah ancaman militer. 2. Narkoba, korupsi, dan kejahatan siber adalah ancaman nonmiliter. 3. Patokannya sederhana: melibatkan kekuatan bersenjata = militer, tanpa senjata = nonmiliter." },
    { q: "Contoh ancaman nonmiliter terhadap NKRI adalah ....", options: ["pemberontakan bersenjata", "sabotase instalasi militer", "penyebaran paham yang bertentangan dengan Pancasila lewat media sosial", "agresi udara"], answer: 2, solution: "1. Penyebaran ideologi yang bertentangan dengan Pancasila adalah ancaman nonmiliter berdimensi ideologi. 2. Pemberontakan bersenjata, sabotase, dan agresi udara memakai kekuatan senjata sehingga tergolong militer. 3. Ancaman nonmiliter sering tidak kasatmata: ideologi, hoaks, dan propaganda." },
    { q: "Gerakan bersenjata yang bertujuan memisahkan suatu daerah dari NKRI termasuk ancaman ....", options: ["nonmiliter berdimensi ekonomi", "nonmiliter berdimensi budaya", "bencana alam", "militer berupa pemberontakan bersenjata"], answer: 3, solution: "1. Separatisme yang menggunakan senjata tergolong pemberontakan bersenjata, yaitu ancaman militer. 2. Ancaman militer selalu melibatkan kekuatan bersenjata. 3. Bedakan dengan cermat: propaganda separatisme di media sosial = nonmiliter, mengangkat senjata = militer." },
    { q: "Terorisme yang menggunakan kekerasan bersenjata untuk menimbulkan ketakutan massal tergolong ancaman ....", options: ["militer", "nonmiliter berdimensi ekonomi", "bencana sosial biasa", "pelanggaran lalu lintas"], answer: 0, solution: "1. Aksi teror bersenjata termasuk ancaman militer. 2. Terorisme memakai kekerasan senjata untuk tujuan politik. 3. Jangan anggap terorisme sekadar kriminal biasa: skalanya mengancam keamanan negara." },
    { q: "Upaya bela negara warga dalam menghadapi kejahatan siber (cyber crime) adalah ....", options: ["meretas balik situs pelaku", "menyebarkan data pribadi pelaku ke media sosial", "tidak menyebarkan hoaks dan melaporkan konten jahat", "membeli antivirus bajakan"], answer: 2, solution: "1. Literasi digital adalah senjatanya: saring sebelum sharing dan laporkan konten jahat ke aparat. 2. Meretas balik dan menyebar data pribadi justru melanggar hukum. 3. Melawan kejahatan siber tidak perlu menjadi hacker — cukup menjadi warga digital yang cerdas." },
    { q: "Dito lebih memilih membeli sepatu buatan pengrajin lokal daripada merek luar negeri yang lebih mahal. Sikap Dito menunjukkan ....", options: ["cinta tanah air dengan bangga pada produk dalam negeri", "sikap konsumtif", "kurang menghargai kualitas", "sikap anti asing"], answer: 0, solution: "1. Bangga dan memakai produk dalam negeri adalah wujud cinta tanah air di bidang ekonomi. 2. Sikap ini mendukung kemandirian ekonomi bangsa. 3. Bedakan: cinta produk lokal = nasionalisme ekonomi, sedangkan membenci bangsa lain = chauvinisme." },
    { q: "Contoh melestarikan budaya daerah sebagai wujud cinta tanah air adalah ....", options: ["mempelajari dan memakai batik serta tarian daerah", "mengganti nama daerah dengan bahasa asing", "meninggalkan upacara adat karena kuno", "menonton film asing setiap hari"], answer: 0, solution: "1. Melestarikan budaya berarti memakai, mempelajari, dan mewariskan budaya daerah. 2. Budaya yang lestari memperkuat identitas dan jati diri bangsa. 3. Modern bukan berarti meninggalkan budaya: keduanya bisa berjalan bersama." },
    { q: "Kegiatan yang mencerminkan bela negara di bidang lingkungan hidup adalah ....", options: ["membuang sampah ke sungai agar cepat hanyut", "menebang pohon untuk lahan parkir", "ikut kerja bakti membersihkan lingkungan dan menanam pohon", "membakar sampah plastik setiap hari"], answer: 2, solution: "1. Lingkungan yang lestari adalah ketahanan nasional di bidang sumber daya alam. 2. Kerja bakti dan menanam pohon menjaga daya dukung lingkungan. 3. Bela negara tidak hanya soal senjata: menjaga alam berarti menjaga masa depan bangsa." },
    { q: "Wilayah NKRI terdiri atas ....", options: ["wilayah darat saja", "wilayah darat dan laut saja", "wilayah darat, laut, dan udara", "wilayah darat dan udara saja"], answer: 2, solution: "1. Indonesia sebagai negara kepulauan memiliki wilayah darat, perairan (laut), dan ruang udara di atasnya. 2. Pasal 25A UUD 1945 menegaskan Indonesia adalah negara kepulauan yang berciri nusantara. 3. Jangan lupakan ruang udara: pelanggaran wilayah udara oleh asing pun pelanggaran kedaulatan." },
    { q: "Wawasan nusantara pada hakikatnya adalah ....", options: ["program transmigrasi penduduk", "rencana pembangunan lima tahun", "sistem pemerintahan daerah", "cara pandang bangsa Indonesia tentang diri dan lingkungannya yang mengutamakan persatuan"], answer: 3, solution: "1. Wawasan nusantara adalah cara pandang bangsa Indonesia tentang diri dan lingkungannya dengan mengutamakan persatuan dan kesatuan. 2. Wawasan ini menjadi pedoman dalam mencapai tujuan nasional. 3. Jangan tertukar dengan otonomi daerah: wawasan nusantara soal cara pandang, bukan struktur pemerintahan." },
    { q: "Lagu kebangsaan Indonesia Raya diciptakan oleh ....", options: ["Ismail Marzuki", "Cornel Simanjuntak", "Kusbini", "W.R. Supratman"], answer: 3, solution: "1. Wage Rudolf Supratman adalah pencipta lagu Indonesia Raya. 2. Ismail Marzuki menciptakan lagu-lagu perjuangan seperti Halo-Halo Bandung, bukan Indonesia Raya. 3. Indonesia Raya pertama kali diperdengarkan pada Kongres Pemuda II, 28 Oktober 1928." },
    { q: "Lagu Indonesia Raya pertama kali diperdengarkan pada peristiwa ....", options: ["Proklamasi 17 Agustus 1945", "Kongres Pemuda II 28 Oktober 1928", "Konferensi Meja Bundar 1949", "Sidang PPKI 18 Agustus 1945"], answer: 1, solution: "1. Indonesia Raya diperdengarkan pertama kali pada penutupan Kongres Pemuda II, 28 Oktober 1928. 2. Saat itu lagu dimainkan tanpa teks (instrumentalia biola) karena diawasi pemerintah kolonial Belanda. 3. Ingat rangkaiannya: 1928 lagu lahir, 1945 ditetapkan sebagai lagu kebangsaan." },
    { q: "Menurut UUD 1945, ketentuan tentang lagu kebangsaan Indonesia diatur dalam ....", options: ["Pasal 35", "Pasal 36", "Pasal 36A", "Pasal 36B"], answer: 3, solution: "1. Pasal 36B UUD 1945 berbunyi: Lagu Kebangsaan ialah Indonesia Raya. 2. Pasal 35 mengatur bendera (Sang Merah Putih) dan Pasal 36A mengatur lambang negara (Garuda Pancasila). 3. Hafalkan urutannya: 35 bendera, 36A lambang, 36B lagu — huruf B mengingatkan pada bunyi lagu." },
    { q: "Warna merah dan putih pada bendera Sang Saka Merah Putih melambangkan ....", options: ["keberanian dan kesucian", "darah dan air mata", "matahari dan bulan", "api dan air"], answer: 0, solution: "1. Merah melambangkan keberanian, putih melambangkan kesucian. 2. Makna ini diwarisi dari panji-panji kerajaan Nusantara zaman dahulu. 3. Jangan tertukar dengan tafsir bebas: makna resmi bendera negara adalah berani dan suci." },
    { q: "Ketika bendera Sang Merah Putih dikibarkan dalam upacara, sikap yang benar adalah ....", options: ["duduk santai sambil bertepuk tangan", "berdiri tegak dengan sikap hormat", "berlari kecil mengikuti irama lagu", "berbicara dengan teman di samping"], answer: 1, solution: "1. UU No. 24 Tahun 2009 mewajibkan setiap orang yang hadir berdiri tegak dengan sikap hormat. 2. Bagi yang berseragam, sikap hormat dilakukan dengan memberi hormat (salute). 3. Menghormati bendera berarti menghormati negara — bukan sekadar aturan upacara." },
    { q: "Perbuatan yang dilarang terhadap bendera negara menurut UU No. 24 Tahun 2009 adalah ....", options: ["mengibarkan bendera yang rusak atau kusam", "mengibarkan bendera setiap hari besar nasional", "memasang bendera di kantor pemerintahan", "mengibarkan bendera setengah tiang saat berkabung"], answer: 0, solution: "1. Dilarang mengibarkan bendera yang rusak, robek, luntur, kusut, atau kusam. 2. Dilarang juga merobek, menginjak, membakar bendera, atau memakainya untuk reklame. 3. Mengibarkan bendera setengah tiang justru aturan resmi sebagai tanda berkabung nasional — bukan pelanggaran." },
    { q: "Pasal 30 ayat (1) UUD 1945 menegaskan bahwa ....", options: ["hanya TNI yang wajib membela negara", "pertahanan negara diserahkan ke negara sahabat", "warga sipil dilarang ikut pertahanan negara", "tiap warga negara berhak dan wajib ikut serta dalam usaha pertahanan dan keamanan negara"], answer: 3, solution: "1. Bunyi Pasal 30 ayat (1): tiap-tiap warga negara berhak dan wajib ikut serta dalam usaha pertahanan dan keamanan negara. 2. Ayat ini menegaskan bela negara milik seluruh rakyat, bukan hanya aparat. 3. Bedakan dengan Pasal 27 ayat (3): keduanya soal pembelaan negara, tetapi Pasal 30 lebih rinci mengatur pertahanan dan keamanan." },
    { q: "Peran TNI dan Polri dalam sistem pertahanan dan keamanan rakyat semesta adalah sebagai ....", options: ["kekuatan pendukung", "kekuatan utama", "pengamat netral", "pasukan cadangan"], answer: 1, solution: "1. Pasal 30 ayat (2): TNI dan Polri sebagai kekuatan utama, sedangkan rakyat sebagai kekuatan pendukung. 2. TNI menjadi kekuatan utama di bidang pertahanan, Polri di bidang keamanan. 3. Jangan tertukar: rakyat = pendukung, TNI dan Polri = utama." }
  ]
};
